window.__CH("c5",["<div class=\"hw\">B, b</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第2字.</div>\r\n","<div class=\"hw\">babae</div><div class=\"pos\"><i>int</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(驚き・喜びを表わす)おやまあ, すてきだ.</div>\r\n","<div class=\"hw\">babaecalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">道楽者, 遊蕩児.</div>\r\n","<div class=\"hw\">Babel</div><div class=\"pos\">-ēlis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">バベル《Assyria の首都》.</div>\r\n","<div class=\"hw\">Babylō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> Babylon 人.</div><div class=\"def\"><num>②</num> (一般に)大富豪.</div>\r\n","<div class=\"hw\">Babylōn</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バビュローン, <SUP>∥</SUP>バビロン《Babylonia の首都》.</div>\r\n","<div class=\"hw\">Babylōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://Babylōn\">Babylōn</a>]</div><div class=\"def\">バビュローニア, <SUP>∥</SUP>バビロニア《 (1) Mesopotamia 南部の古代帝国. (2) =<a href=\"entry://Babylōn\">Babylon</a>》.</div>\r\n","<div class=\"hw\">Babylōniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Babylōnius\">Babylonius</a>.</div>\r\n","<div class=\"hw\">Babylōnica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Babylōnicus\">Babylōnicus</a>]</div><div class=\"def\">Babylonia のつづれ織.</div>\r\n","<div class=\"hw\">Babylōnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Babylōnius\">Babylonius</a>.</div>\r\n","<div class=\"hw\">Babylōniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Babylōnius\">Babylonius</a>.</div>\r\n","<div class=\"hw\">Babylōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Babylon [Babylonia] の.</div><div class=\"hw2\"><b>Babylōniī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Babylon [Babylonia] 人.</div>\r\n","<div class=\"hw\">Bacaudae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">=<a href=\"entry://Bagaudae\">Bagaudae</a>.</div>\r\n","<div class=\"hw\">bacca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://bāca\">baca</a>.</div>\r\n","<div class=\"hw\">baccar</div><div class=\"pos\">-aris, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙シクラメンの一種.</div>\r\n","<div class=\"hw\">baccaris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://baccar\">baccar</a>.</div>\r\n","<div class=\"hw\">Baccha</div><div class=\"pos\">-ae, <B>-chē</B> -ēs, <i>f</i></div><div class=\"def\">Bacchus の女信徒.</div>\r\n","<div class=\"hw\">Bacchantēs</div><div class=\"pos\">-ium [-um], <i>f pl</i></div><div class=\"ori\">[bacchor]</div><div class=\"def\">Bacchus の女信徒たち.</div>\r\n","<div class=\"hw\">bacchiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙長短短長格の(=<a href=\"entry://choriambicus\">choriambicus</a>).</div>\r\n","<div class=\"hw\">Bacchiadae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バッキアダエ, <SUP>*</SUP>-ダイ《Corinthus の古い王族;Syracusae 市を建設した(前734)》.</div>\r\n","<div class=\"hw\">Bacchicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bacchus の.</div><hr><div class=\"hw\">Bacchicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Bacchīus\">Bacchius</a>.</div>\r\n","<div class=\"hw\">Bacchis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> =<a href=\"entry://Baccha\">Baccha</a>.</div><div class=\"def\"><num>②</num> バッキス《 (1) ギリシアの女性名.(2)(<i>pl</i>)<i>Bacchides</i> 「バッキス姉妹」;Plautus の喜劇》.</div>\r\n","<div class=\"hw\">bacchor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"ori\">[↓<a href=\"entry://Bacchus\">Bacchus</a>]</div><div class=\"def\"><num>①</num> Bacchus 祭をする.</div><div class=\"def\"><num>②</num> 飲み騒ぐ;荒れ狂う.</div><div class=\"def\"><num>③</num> (狂乱して)さまよう.</div>\r\n","<div class=\"hw\">Bacchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙バックス, <SUP>*</SUP>バッコス, <SUP>∥</SUP>バッカス《Juppiter と Semele の息子;酒神》.</div><div class=\"def\"><num>②</num> Bacchus への叫び声.</div><div class=\"def\"><num>③</num> ブドウの木.</div><div class=\"def\"><num>④</num> ぶどう酒.</div>\r\n","<div class=\"hw\">bacchābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bacchor]</div><div class=\"def\">(Bacchantes のように)飲み騒ぐ.</div>\r\n","<div class=\"hw\">Bacchānal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"def\">Bacchus 祭が行なわれた場所.</div>\r\n","<div class=\"hw\">Bacchānālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↑<a href=\"entry://Bacchānal\">Bacchānal</a>]</div><div class=\"def\">Bacchus 祭(=<a href=\"entry://Dionȳsia\">Dionysia</a>).</div>\r\n","<div class=\"hw\">Bacchānālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Bacchus の.</div>\r\n","<div class=\"hw\">bacchātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[bacchor]</div><div class=\"def\">Bacchantes のように.</div>\r\n","<div class=\"hw\">bacchātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[bacchor]</div><div class=\"def\"><num>①</num> Bacchus 祭.</div><div class=\"def\"><num>②</num> 暴飲乱舞の酒宴.</div>\r\n","<div class=\"hw\">bacchātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://bacchor\">bacchor</a>.</div>\r\n","<div class=\"hw\">Bacchēis</div><div class=\"pos\">-idos, <i>adj f</i></div><div class=\"def\">Bacchiadae の祖 Bacchis にゆかりの;《詩》Corinthus の.</div>\r\n","<div class=\"hw\">Bacchēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bacchus の.</div>\r\n","<div class=\"hw\">Bacchēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Bacchēius\">Baccheius</a>.</div>\r\n","<div class=\"hw\">Bacchīus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘詩〙Bacchus 格《長長短または短長長格》.</div>\r\n","<div class=\"hw\">baccīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙ナス属の植物の一種.</div>\r\n","<div class=\"hw\">baceolus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ばか者(=<a href=\"entry://stultus\">stultus<SUP>2</SUP></a>).</div>\r\n","<div class=\"hw\">bacillum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[baculum]</div><div class=\"def\"><num>①</num> (小さな)棒, 杖.</div><div class=\"def\"><num>②</num> lictor の官杖.</div>\r\n","<div class=\"hw\">bacillus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"def\"><num>①</num> =<a href=\"entry://bacillum\">bacillum</a>.</div><div class=\"def\"><num>②</num> 〘細菌〙バチルス;桿菌.</div>\r\n","<div class=\"hw\">Bactra</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バクトラ《Bactria の首都;現 Balkh》.</div>\r\n","<div class=\"hw\">Bactria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バクトリア《Oxos 川と Paropamisus 山脈の間にギリシア人が建設した王国(前246‐138)》.</div>\r\n","<div class=\"hw\">Bactrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Bactriānus\">Bactrianus</a>.</div>\r\n","<div class=\"hw\">Bactriāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(<i>sc. </i> terra)=<a href=\"entry://Bactria\">Bactria</a>.</div>\r\n","<div class=\"hw\">Bactriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bactra [Bactria] の.</div><div class=\"hw2\"><b>Bactriānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Bactra [Bactria] の住民.</div>\r\n","<div class=\"hw\">Bactrus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バクトルス, <SUP>*</SUP>-ロス《Bactra 付近の川》.</div>\r\n","<div class=\"hw\">Bactrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Bactra [Bactria] の住民.</div>\r\n","<div class=\"hw\">Bactrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Bactriānus\">Bactrianus</a>.</div>\r\n","<div class=\"hw\">bactēriologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">細菌学.</div>\r\n","<div class=\"hw\">bactērium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">細菌, バクテリア.</div>\r\n","<div class=\"hw\">baculum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"def\"><num>①</num> 杖, 棒.</div><div class=\"def\"><num>②</num> 権威の象徴としての杖, 笏権標.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘カト〙司教杖.</div>\r\n","<div class=\"hw\">Bacēnis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">(<i>sc. </i> silva)バケーニス《Germania 中部および東部の大森林》.</div>\r\n","<div class=\"hw\">baditis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙スイレン(=<a href=\"entry://nymphaea\">nymphaea</a>).</div>\r\n","<div class=\"hw\">badius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(馬が)鹿毛<SUB>かげ</SUB>(色)の, 栗毛の.</div>\r\n","<div class=\"hw\">badizō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">歩く, 行進する.</div>\r\n","<div class=\"hw\">Baduhennae lūcus</div><div class=\"pos\"><i>m</i></div><div class=\"def\">バドゥヘンナの森《Germania 北部の森林》.</div>\r\n","<div class=\"hw\">Baebius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">バエビウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Baecula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バエクラ《Hispania Baetica の町;現 Bailén》.</div>\r\n","<div class=\"hw\">Baetica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バエティカ《Hispania 南部地方;現 Andalusia の一部》.</div>\r\n","<div class=\"hw\">Baeticola</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[Baetis/colo<SUP>2</SUP>]</div><div class=\"def\">Baetis 河辺の住民.</div>\r\n","<div class=\"hw\">Baeticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Baetis 川の.</div>\r\n","<div class=\"hw\">Baeticātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Baetica 産の毛織物を着た.</div>\r\n","<div class=\"hw\">Baetigena</div><div class=\"pos\">-ae, <i>adj</i></div><div class=\"ori\">[Baetis/gigno]</div><div class=\"def\">Baetis 河辺に生まれた.</div>\r\n","<div class=\"hw\">Baetis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">バエティス《Hispania 南部の川;現 Guadalquivir》.</div>\r\n","<div class=\"hw\">baetō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">=<a href=\"entry://bītō\">bito</a>.</div>\r\n","<div class=\"hw\">Baetūria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バエトゥーリア《Hispania Baetica の北西部地方》.</div>\r\n","<div class=\"hw\">Bagaudae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">バガウダエ《Gallia の農民の一団;Diocletianus 帝時代に謀反を起こし, 将軍 Maximianus に平定された》.</div>\r\n","<div class=\"hw\">Bagrada</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">バグラダ《Africa の Utica 近くの川;現 Medjerda》.</div>\r\n","<div class=\"hw\">Bagōās</div><div class=\"pos\">-ae, <i>m</i>, <B>-gōus</B> -ī, <i>m</i></div><div class=\"ori\">[<i>Gk<Pers. </i>]</div><div class=\"def\">バゴーアース《ペルシアの宮廷に仕える宦官の総称》.</div>\r\n","<div class=\"hw\">balaninus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バルサムの実から作った.</div>\r\n","<div class=\"hw\">balanophorāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ツチトリモチ科.</div>\r\n","<div class=\"hw\">balanus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> どんぐり.</div><div class=\"def\"><num>②</num> どんぐり状の木の実《ナツメヤシ・クリなど》.</div><div class=\"def\"><num>③</num> 坐薬.</div><div class=\"def\"><num>④</num> 貝の一種.</div>\r\n","<div class=\"hw\">balanātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[balanus]</div><div class=\"def\">バルサムを塗られた.</div>\r\n","<div class=\"hw\">balanītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">どんぐり状の物.</div>\r\n","<div class=\"hw\">balatrō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">道化師, おどけ者.</div>\r\n","<div class=\"hw\">balbus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">どもる, 口ごもる.</div>\r\n","<div class=\"hw\">Balbus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">バルブス《ローマ人の家名;特に <i>L. Cornelius ～</i>, Caesar の同盟者;市民権の不正取得の嫌疑で訴追され, Cicero の弁護を受けた》.</div>\r\n","<div class=\"hw\">balbē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://balbus\">balbus</a>]</div><div class=\"def\"><num>①</num> 口ごもりながら.</div><div class=\"def\"><num>②</num> あいまいに.</div>\r\n","<div class=\"hw\">balbūtiō</div><div class=\"pos\">-īre, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[balbus]</div><div class=\"def\"><num>①</num> どもる, 口ごもる;どもりながら言う.</div><div class=\"def\"><num>②</num> あいまいに話す 〈de re〉.</div>\r\n","<div class=\"hw\">Balcia, -tia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バルキア《Scythia から3日の航海で着くという大きな島;Scadinavia の古名》.</div>\r\n","<div class=\"hw\">baldachīnus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘カト〙(祭壇上の, または聖体行列用の)天蓋.</div>\r\n","<div class=\"hw\">baline-</div><div class=\"def\">⇒balne-.</div>\r\n","<div class=\"hw\">Baliāricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Baliāris\">Baliaris</a>.</div><div class=\"hw2\"><b>Baliāricī</b></div><div class=\"pos2\">-orum, <i>m pl</i></div><div class=\"def2\">=<a href=\"entry://Baliāris\">Baliares<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Baliāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Baliares 諸島の.</div><div class=\"hw2\"><b>Baliārēs</b><SUP>2</SUP></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Baliares 諸島の住民.</div>\r\n","<div class=\"hw\">Baliārēs<SUP>1</SUP>, Baleārēs (insulae)</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">バリアーレース諸島《地中海西部の諸島》.</div>\r\n","<div class=\"hw\">ballaena</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://bālaena\">balaena</a>.</div>\r\n","<div class=\"hw\">ballista</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 弩砲, 投石器.</div><div class=\"def\"><num>②</num> 飛び道具.</div>\r\n","<div class=\"hw\">ballistia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ballō\">ballō</a>]</div><div class=\"def\">舞踏曲[歌].</div>\r\n","<div class=\"hw\">ballistārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://ballista\">ballista</a>.</div>\r\n","<div class=\"hw\">Balliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> バッリオー《Plautus の喜劇 <i>Pseudolus</i> に登場する女衒<SUB>ぜげん</SUB>》.</div><div class=\"def\"><num>②</num> くだらぬやつ.</div>\r\n","<div class=\"hw\">ballātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[ballo]</div><div class=\"def\">舞踏, ダンス.</div>\r\n","<div class=\"hw\">ballātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[ballo]</div><div class=\"def\">《碑》舞踏家, 踊り手.</div>\r\n","<div class=\"hw\">ballēmatia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[ballo]</div><div class=\"def\">踊ること.</div>\r\n","<div class=\"hw\">ballō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">踊る, ダンスをする.</div>\r\n","<div class=\"hw\">ballōtē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙シソ科の草.</div>\r\n","<div class=\"hw\">balneae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>balnea</B> -ōrum, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://balneum\">balneum 1</a>.</div>\r\n","<div class=\"hw\">balneolae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl dim</i></div><div class=\"def\">=<a href=\"entry://balneolum\">balneolum</a>.</div>\r\n","<div class=\"hw\">balneolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://balneum\">balneum</a>]</div><div class=\"def\">小浴場.</div>\r\n","<div class=\"hw\">balneum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 浴場.</div><div class=\"def\"><num>②</num> 浴槽.</div><div class=\"def\"><num>③</num> 入浴.</div>\r\n","<div class=\"hw\">balneāria<SUP>1</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[balnearius]</div><div class=\"def\">=<a href=\"entry://balneum\">balneum 1</a>.</div><hr><div class=\"hw\">balneāria<SUP>2</SUP></div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://balneāris\">balneāris</a>]</div><div class=\"def\">入浴用具.</div>\r\n","<div class=\"hw\">balneāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://balneārius\">balnearius</a>.</div>\r\n","<div class=\"hw\">balneārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[balneum]</div><div class=\"def\">浴場[入浴]の.</div>\r\n","<div class=\"hw\">balneātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[balneum]</div><div class=\"def\">浴場管理人.</div>\r\n","<div class=\"hw\">balneātrix</div><div class=\"pos\">-īcis</div><div class=\"ori\">[↑<a href=\"entry://balneātor\">balneātor</a>]</div><div class=\"def\">浴場管理人《女性》.</div>\r\n","<div class=\"hw\">balneō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[balneum]</div><div class=\"def\">入浴する.</div>\r\n","<div class=\"hw\">balsamināceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ツリフネソウ科.</div>\r\n","<div class=\"hw\">balsamum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\"><num>①</num> 〘植〙バルサム樹.</div><div class=\"def\"><num>②</num> バルサム.</div>\r\n","<div class=\"hw\">balteus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"def\"><num>①</num> 帯, ベルト;剣帯;(馬首の)飾り帯.</div><div class=\"def\"><num>②</num> 〘天〙黄道帯.</div><div class=\"def\"><num>③</num> 〘建〙バルテウス《イオニア式柱頭の渦巻をつなぐ帯》.</div><div class=\"def\"><num>④</num> 円形競技場の上部席と下部席を分ける周回通路》.</div>\r\n","<div class=\"hw\">balux</div><div class=\"pos\">-ūcis, <i>f</i></div><div class=\"def\">砂金.</div>\r\n","<div class=\"hw\">Bambaliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> balbus]</div><div class=\"def\">(「どもる人」 の意)Antonius の妻 Fulvia の父 M. Fulvius のあだ名.</div>\r\n","<div class=\"hw\">Bandusia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バンドゥシア《Horatius の生地 Venusia 付近の泉》.</div>\r\n","<div class=\"hw\">bangialēs</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ウシケノリ目.</div>\r\n","<div class=\"hw\">bangiāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ウシケノリ科.</div>\r\n","<div class=\"hw\">banna</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">結婚予告.</div>\r\n","<div class=\"hw\">Bantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バンティア《Apulia の町;現 Banzi》.</div>\r\n","<div class=\"hw\">Bantīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bantia の.</div>\r\n","<div class=\"hw\">baphīum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">染め物工場.</div>\r\n","<div class=\"hw\">baptisma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 浸すこと, 洗うこと.</div><div class=\"def\"><num>②</num> 〘キ教〙洗礼.</div>\r\n","<div class=\"hw\">baptismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘キ教〙洗礼.</div>\r\n","<div class=\"hw\">baptismālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://baptisma\">baptisma</a>]</div><div class=\"def\">〘キ教〙洗礼の.</div>\r\n","<div class=\"hw\">baptista</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘キ教〙洗礼を授ける人(=洗礼者ヨハネ(Joannes)).</div>\r\n","<div class=\"hw\">baptistērium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 浴槽.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘キ教〙洗礼盤.</div>\r\n","<div class=\"hw\">baptizātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[baptizo]</div><div class=\"def\">〘キ教〙洗礼を授けること.</div>\r\n","<div class=\"hw\">baptizātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://baptizō\">baptizō</a>]</div><div class=\"def\">〘キ教〙洗礼を授ける人.</div>\r\n","<div class=\"hw\">baptizō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘キ教〙洗礼を授ける.</div>\r\n","<div class=\"hw\">barathrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">深淵, 割れ目;奈落, 地獄.</div>\r\n","<div class=\"hw\">barba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ひげ, あごひげ.</div>\r\n","<div class=\"hw\">barbara</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[barbarus<SUP>2</SUP>]</div><div class=\"def\">(女性の)異国人;野蛮人.</div>\r\n","<div class=\"hw\">barbaria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[barbarus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 外国, 異国;未開地.</div><div class=\"def\"><num>②</num> 粗野.</div><div class=\"def\"><num>③</num> 野蛮.</div>\r\n","<div class=\"hw\">barbaricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://barbarus\">barbarus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">barbaricē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://barbaricus\">barbaricus</a>]</div><div class=\"def\">異国風に.</div>\r\n","<div class=\"hw\">barbarismus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">言語使用上の間違い, 破格語法[構文].</div>\r\n","<div class=\"hw\">barbarizō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[barbarus]</div><div class=\"def\">異国人のように話す, 破格語法を使う.</div>\r\n","<div class=\"hw\">barbariēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"def\">=<a href=\"entry://barbaria\">barbaria</a>.</div>\r\n","<div class=\"hw\">barbarolexis</div><div class=\"pos\">-eos [-is], <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://barbarus\">barbarus<SUP>1</SUP></a>/lexis]</div><div class=\"def\">外国語を(特にギリシア語をラテン語風に)誤用すること.</div>\r\n","<div class=\"hw\">barbarus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (ギリシアあるいはギリシア・ローマ以外の)外国[異国]の.</div><div class=\"def\"><num>②</num> 野蛮な.</div><div class=\"def\"><num>③</num> 粗野な.</div><hr><div class=\"hw\">barbarus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">異国人;野蛮人.</div>\r\n","<div class=\"hw\">barbarē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[barbarus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 外国語で.</div><div class=\"def\"><num>②</num> 粗野に.</div><div class=\"def\"><num>③</num> 野蛮に.</div>\r\n","<div class=\"hw\">barbiger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[barba/gero]</div><div class=\"def\">ひげを生やした.</div>\r\n","<div class=\"hw\">barbitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[barba]</div><div class=\"def\">ひげ;ひげが生えること.</div>\r\n","<div class=\"hw\">barbiton</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://barbitos\">barbitos 1</a>.</div>\r\n","<div class=\"hw\">barbitos</div><div class=\"pos\">-ī, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (低音の)竪琴, リラ.</div><div class=\"def\"><num>②</num> barbitos に合わせて歌う歌.</div>\r\n","<div class=\"hw\">barbitālum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙バルビタール.</div>\r\n","<div class=\"hw\">barbula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[barba]</div><div class=\"def\">うぶひげ.</div>\r\n","<div class=\"hw\">barbus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[barba]</div><div class=\"def\">〘魚〙バーベル《上あごに触鬚<SUB>しょくしゅ</SUB>が4本あるコイ科の魚》.</div>\r\n","<div class=\"hw\">barbātulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://barbātus\">barbātus<SUP>1</SUP></a>]</div><div class=\"def\">(少し)ひげの生えた.</div>\r\n","<div class=\"hw\">barbātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[barba]</div><div class=\"def\">ひげの生えた.</div><hr><div class=\"hw\">barbātus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 古い時代のローマ人《ひげを生やしていたため》.</div><div class=\"def\"><num>②</num> 哲学者.</div><div class=\"def\"><num>③</num> ヤギ.</div>\r\n","<div class=\"hw\">barbātōria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[barba]</div><div class=\"def\">ひげを初めて剃る儀式.</div>\r\n","<div class=\"hw\">barca</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">小舟, はしけ.</div>\r\n","<div class=\"hw\">Barca, -cās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">バルカ《Carthago の有力な一家;Hamilcar, Hannibal がこれに属した》.</div>\r\n","<div class=\"hw\">Barcaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Barca 家の.</div>\r\n","<div class=\"hw\">Barcaeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Barce の住民.</div>\r\n","<div class=\"hw\">barcala</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">愚者, とんま.</div>\r\n","<div class=\"hw\">Barcē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バルケー《Cyrenaica の町》.</div>\r\n","<div class=\"hw\">Barcīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Barca 家の.</div><div class=\"hw2\"><b>Barcīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Barca 家の人々.</div>\r\n","<div class=\"hw\">Bardaeī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">=<a href=\"entry://Vardaeī\">Vardaei</a>.</div>\r\n","<div class=\"hw\">Bardaicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bardaei 族の</div><div class=\"ex\"><i>calceus ～</i> (<author>J<small>UV</small></author>)<span class=\"ext\">軍靴;軍人.</span></div>\r\n","<div class=\"hw\">bardus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">愚鈍な, ばかな.</div>\r\n","<div class=\"hw\">bardītus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Germania 人の戦の歌.</div>\r\n","<div class=\"hw\">Bargyliae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>Bargylia</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バルギュリアエ, <SUP>*</SUP>-リア《Caria の町》.</div>\r\n","<div class=\"hw\">Bargyliētae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Bargyliae の住民.</div>\r\n","<div class=\"hw\">Bargyliēticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bargyliae の.</div>\r\n","<div class=\"hw\">Bargūsiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バルグーシイー, <SUP>*</SUP>-シオイ《Hispania Tarraconensis にいた一部族》.</div>\r\n","<div class=\"hw\">barinulae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">水脈を探る人, 水脈占者(=<a href=\"entry://aquilex\">aquilex</a>).</div>\r\n","<div class=\"hw\">barium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙バリウム.</div>\r\n","<div class=\"hw\">barriō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"ori\">[barrus]</div><div class=\"def\">(象がらっぱのように)鳴く.</div>\r\n","<div class=\"hw\">barrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘動〙ゾウ.</div>\r\n","<div class=\"hw\">barrītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://barriō\">barriō</a>]</div><div class=\"def\"><num>①</num> (象のらっぱのような)鳴き声.</div><div class=\"def\"><num>②</num> 鬨<SUB>とき</SUB>の声.</div>\r\n","<div class=\"hw\">barycephalus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(建物の)上部が重すぎる.</div>\r\n","<div class=\"hw\">baryta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘化〙バリタ, 重土.</div>\r\n","<div class=\"hw\">basanītēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鉱〙(試金石として用いられた)玄武岩の一種.</div>\r\n","<div class=\"hw\">bascauda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">食器を入れるかご.</div>\r\n","<div class=\"hw\">basidiomycētēs</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙担子菌亜門.</div>\r\n","<div class=\"hw\">basileus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">王;東ローマ皇帝.</div>\r\n","<div class=\"hw\">basilica</div><div class=\"pos\">-ae <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> バシリカ《広場(forum)の近くにあって裁判・商取引などに用いられた公共の建物》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘カト〙バシリカ聖堂《特権を与えられた聖堂》.</div>\r\n","<div class=\"hw\">Basilica</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">バシリカ法典《10世紀初頭, 東ローマ皇帝 Leo 6世の治世下に制定された法典;ギリシア語で書かれた》.</div>\r\n","<div class=\"hw\">basilicon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">軟膏の一種.</div>\r\n","<div class=\"hw\">basilicula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[basilica]</div><div class=\"def\">小聖堂.</div>\r\n","<div class=\"hw\">basilicum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://basilicus\">basilicus</a>]</div><div class=\"def\"><num>①</num> 王侯のような衣装.</div><div class=\"def\"><num>②</num> サイコロの最高の目.</div>\r\n","<div class=\"hw\">basilicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">王侯の, 王侯らしい.</div>\r\n","<div class=\"hw\">basilicē<SUP>1</SUP></div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://basilicon\">basilicon</a>.</div><hr><div class=\"hw\">basilicē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[basilicus]</div><div class=\"def\">王侯らしく, りっぱに.</div>\r\n","<div class=\"hw\">basiliscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バシリスク《Africa の砂漠に住み, 人をにらみ殺すという伝説上の爬虫類》.</div>\r\n","<div class=\"hw\">Basilēa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">バシレーア《Rhenus 河畔にあった Rauraci 族の町;現 Basel》.</div>\r\n","<div class=\"hw\">basilēum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://basilīum\">basilium</a>.</div>\r\n","<div class=\"hw\">Basilīa<SUP>1</SUP></div><div class=\"pos\">-ōn, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘聖〙(旧約聖書の)列王記.</div><hr><div class=\"hw\">Basilīa<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> =<a href=\"entry://Balcia\">Balcia</a>.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> =<a href=\"entry://Basilēa\">Basilea</a>.</div>\r\n","<div class=\"hw\">basilīum, -ēum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》</div><div class=\"def\"><num>①</num> 王冠.</div><div class=\"def\"><num>②</num> 眼薬の一種.</div>\r\n","<div class=\"hw\">basis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘建〙台座, 礎石.</div><div class=\"def\"><num>②</num> 〘数〙(三角形の)底辺.</div>\r\n","<div class=\"hw\">basivertebrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[basis/vertebra]</div><div class=\"def\">〘解〙椎体の.</div>\r\n","<div class=\"hw\">Bassareus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bacchus の呼称の一つ.</div>\r\n","<div class=\"hw\">Bassaricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://Bassareus\">Bassareus</a>]</div><div class=\"def\">Bacchus の.</div>\r\n","<div class=\"hw\">Bassaris</div><div class=\"pos\">-idos, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bacchus の女信徒.</div>\r\n","<div class=\"hw\">Bassus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">バッスス《ローマ人の家名》.</div>\r\n","<div class=\"hw\">Bassānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バッサーニア《Illyria 北東部の町;現 Elbassan》.</div>\r\n","<div class=\"hw\">Bassānītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Bassania の住民.</div>\r\n","<div class=\"hw\">Bastarnae, -sternae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">バスタルナエ《Danubius 川下流域にいた Germania の一部族》.</div>\r\n","<div class=\"hw\">basterna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">かご, 輿<SUB>こし</SUB>.</div>\r\n","<div class=\"hw\">bastum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">杖, 棒.</div>\r\n","<div class=\"hw\">basālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[basis]</div><div class=\"def\">〘解〙基底の.</div>\r\n","<div class=\"hw\">bat</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">=<a href=\"entry://at\">at</a>《喜劇で at をもじって造った語》.</div>\r\n","<div class=\"hw\">bathrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》基部, 土台.</div>\r\n","<div class=\"hw\">Bathyllus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バテュッルス, <SUP>*</SUP>-ロス《 (1) Samos 島生まれの美少年;Anacreon に愛された.(2) Alexandria 生まれの喜劇役者で, Maecenas お気に入りの解放奴隷》.</div>\r\n","<div class=\"hw\">batillum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://vatillum\">vatillum</a>.</div>\r\n","<div class=\"hw\">batioca, batiola</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">酒杯.</div>\r\n","<div class=\"hw\">batis</div><div class=\"pos\">-is [-idis], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙海岸の岩に生えるセリ科の草.</div>\r\n","<div class=\"hw\">batrachion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙キンポウゲ属の植物(=<a href=\"entry://rānunculus\">ranunculus 2</a>).</div>\r\n","<div class=\"hw\">Batrachomyomachia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(「カエルとネズミの合戦」 の意)Homerus 作と伝えられる小叙事詩.</div>\r\n","<div class=\"hw\">batrachus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙(おそらく)アンコウ.</div>\r\n","<div class=\"hw\">Battiadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Battus の子孫《 (1) Cyrene の住民.(2) 詩人 Callimachus》.</div>\r\n","<div class=\"hw\">Battus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙バットゥス, <SUP>*</SUP>-トス《Cyrene の伝説上の創建者》.</div>\r\n","<div class=\"hw\">battuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://battuō\">battuo</a>.</div>\r\n","<div class=\"hw\">battuō</div><div class=\"pos\">-ere -uī, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 打つ, たたく.</div><div class=\"def\"><num>②</num> (剣闘士が)撃ち合いをする 〈cum alqo〉.</div>\r\n","<div class=\"hw\">Batulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">バトゥルム《Campania の町;現 Baja》.</div>\r\n","<div class=\"hw\">batus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙キイチゴ.</div>\r\n","<div class=\"hw\">Batāvia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">バターウィア《Batavi 族の国;現在のオランダの一部》.</div>\r\n","<div class=\"hw\">Batāvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Batavia の, Batavi 族の.</div>\r\n","<div class=\"hw\">Batāvī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">バターウィー《Rhenus 川下流域にいた Germania の一部族》.</div>\r\n","<div class=\"hw\">Batō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">バトー《Dalmatia における反乱(後6年)の指導者》.</div>\r\n","<div class=\"hw\">Batōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》Bato の.</div>\r\n","<div class=\"hw\">baubor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">(犬が)ほえる.</div>\r\n","<div class=\"hw\">Baucis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙バウキス《Phrygia の貧しい農夫 Philemon の妻;Juppiter と Mercurius が人間の姿をして Phrygia へ来た時に夫とともに2神を厚遇したため, 2本の聖木に変えられた》.</div>\r\n","<div class=\"hw\">Baulī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">バウリー《Campania の Baiae 付近の町》.</div>\r\n","<div class=\"hw\">Bavius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">バウィウス《Vergilius と同時代の詩人》.</div>\r\n","<div class=\"hw\">baxea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">サンダルに似た履物.</div>\r\n","<div class=\"hw\">bdellium</div><div class=\"pos\">-ī, <i>n</i>, <B>bdella</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙ヤシの一種.</div><div class=\"def\"><num>②</num> bdellium から採る芳香樹脂.</div>\r\n","<div class=\"hw\">beber</div><div class=\"pos\">-brī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘動〙ビーバー(=<a href=\"entry://fiber\">fiber</a>).</div>\r\n","<div class=\"hw\">Bebryces</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベブリュケス《 (1) 小アジア北西部にいた一部族.(2) Gallia Narbonensis にいた一部族》.</div>\r\n","<div class=\"hw\">Bebrycia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベブリュキア(ー)《Bebryces (1) の国;のちに Bithynia》.</div>\r\n","<div class=\"hw\">Bebrycius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Bebrycia の.</div><div class=\"def\"><num>②</num> Bebryces (2) の.</div>\r\n","<div class=\"hw\">Bebryx</div><div class=\"pos\">-ycis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Bebrycia 人《特にその王 Amycus》.</div><div class=\"def\"><num>②</num> 〘伝説〙ベブリュクス《Bebryces (2) の王;その娘 Pyrene が montes Pyrenaei(ピレネー山脈)に名を与えた》.</div>\r\n","<div class=\"hw\">bebrīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://beber\">beber</a>]</div><div class=\"def\">ビーバーの.</div>\r\n","<div class=\"hw\">beccus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">くちばし.</div>\r\n","<div class=\"hw\">bee</div><div class=\"def\">メー《羊の鳴き声を表わす擬声語》.</div>\r\n","<div class=\"hw\">Beelzebūb, -būle</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙ベエルゼブーブ, <SUP>∥</SUP>ベルゼブル《悪魔の長》.</div>\r\n","<div class=\"hw\">Begerrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Bigerriōnes\">Bigerriones</a>.</div>\r\n","<div class=\"hw\">begoniāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙シュウカイドウ科.</div>\r\n","<div class=\"hw\">behemōth</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">カバ.</div>\r\n","<div class=\"hw\">Belgae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">ベルガエ《Gallia 北部にいた好戦的な部族》.</div>\r\n","<div class=\"hw\">Belgica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Belgium\">Belgium</a>.</div>\r\n","<div class=\"hw\">Belgicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Belgae 族の.</div>\r\n","<div class=\"hw\">Belgium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ベルギウム《Belgae 族の国》.</div>\r\n","<div class=\"hw\">Belial</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙ベリアル《「よこしまな者」 の意;のちにサタンを指す》.</div>\r\n","<div class=\"hw\">belion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙ニガクサ属の植物.</div>\r\n","<div class=\"hw\">bellax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[bello]</div><div class=\"def\">戦争の;好戦的な.</div>\r\n","<div class=\"hw\">Bellerophontēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://Bellerophōn\">Bellerophon</a>.</div>\r\n","<div class=\"hw\">Bellerophontēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bellerophon の.</div>\r\n","<div class=\"hw\">Bellerophōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ベッレロポーン《Glaucus の息子で Corinthus の勇士;天馬 Pegasus に乗って怪獣 Chimaera を退治した》.</div>\r\n","<div class=\"hw\">bellicrepus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellum/crepo]</div><div class=\"def\">武具の音のする</div><div class=\"ex\"><i>bellicrepa salutatio</i> (<author>P<small>AUL</small></author>)<span class=\"ext\">剣の舞.</span></div>\r\n","<div class=\"hw\">bellicum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://bellicus\">bellicus</a>]</div><div class=\"def\">戦闘開始の合図</div><div class=\"ex\"><i>～ canere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">突撃らっぱを吹く.</span></div>\r\n","<div class=\"hw\">bellicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellum]</div><div class=\"def\"><num>①</num> 戦争の, 軍の</div><div class=\"ex\"><i>res bellica</i> (<author>C<small>IC</small></author>)<span class=\"ext\">軍事.</span></div><div class=\"def\"><num>②</num> 勇敢な, 好戦的な.</div>\r\n","<div class=\"hw\">bellicōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellicus]</div><div class=\"def\"><num>①</num> 戦争の多い.</div><div class=\"def\"><num>②</num> 好戦的な, 勇敢な.</div>\r\n","<div class=\"hw\">bellifer</div><div class=\"pos\">-fera -ferum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bellum/fero]</div><div class=\"def\">=<a href=\"entry://belliger\">belliger</a>.</div>\r\n","<div class=\"hw\">bellificō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[bellum/facio]</div><div class=\"def\">戦争をしかける, 攻撃する.</div>\r\n","<div class=\"hw\">belliger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[bellum/gero]</div><div class=\"def\"><num>①</num> 好戦的な, 勇敢な.</div><div class=\"def\"><num>②</num> 戦争の.</div>\r\n","<div class=\"hw\">belligeror</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://belligerō\">belligero</a>.</div>\r\n","<div class=\"hw\">belligerātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[belligero]</div><div class=\"def\">敵対[戦闘]行為, 交戦.</div>\r\n","<div class=\"hw\">belligerātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://belligerō\">belligerō</a>]</div><div class=\"def\">戦士, 戦闘員.</div>\r\n","<div class=\"hw\">belligerō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[bellum/gero]</div><div class=\"def\">戦争をする, 戦う 〈<i>abs</i>;cum alqo;adversus alqm〉.</div>\r\n","<div class=\"hw\">bellipotens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[bellum/potens]</div><div class=\"def\">戦で勇ましい.</div>\r\n","<div class=\"hw\">Bellipotens</div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\">軍神(=<a href=\"entry://Mars\">Mars</a>);<i>diva</i> ～ (<author>S<small>TAT</small></author>) =<a href=\"entry://Minerva\">Minerva</a>.</div>\r\n","<div class=\"hw\">bellis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">〘植〙(おそらく)ヒナギク.</div>\r\n","<div class=\"hw\">bellisonus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bellum/sonus]</div><div class=\"def\">戦の響きのする.</div>\r\n","<div class=\"hw\">bellitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[bellus]</div><div class=\"def\">美しさ, 優雅.</div>\r\n","<div class=\"hw\">belliātulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://belliātus\">belliātus</a>]</div><div class=\"def\">きれいな, かわいい.</div>\r\n","<div class=\"hw\">belliātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellus]</div><div class=\"def\">かわいい, きれいな.</div>\r\n","<div class=\"hw\">belliō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">〘植〙アラゲシュンギク.</div>\r\n","<div class=\"hw\">Bellocassī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Veliocassēs\">Veliocasses</a>.</div>\r\n","<div class=\"hw\">bellor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://bellō\">bello</a>.</div>\r\n","<div class=\"hw\">Bellovacī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ベッロウァキー《Gallia Belgica にいた一部族》.</div>\r\n","<div class=\"hw\">bellua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://bēlua\">belua</a>.</div>\r\n","<div class=\"hw\">bellulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[bellus]</div><div class=\"def\">きれいな, 上品な, かわいい.</div>\r\n","<div class=\"hw\">bellulē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://bellulus\">bellulus</a>]</div><div class=\"def\">きれいに, 上品に.</div>\r\n","<div class=\"hw\">bellum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 戦争 〈alcis;cum alqo〉</div><div class=\"ex\"><i>(in)bello = belli</i> (<author>C<small>IC</small></author>)<span class=\"ext\">戦時に</span></div><div class=\"ex\"><i>belli domique</i> (<author>C<small>IC</small></author>)<span class=\"ext\">戦時および平時に</span></div><div class=\"ex\"><i>～ denuntiare [indicere]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">宣戦布告する</span></div><div class=\"ex\"><i>～ componere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">停戦する.</span></div><div class=\"def\"><num>②</num> 戦闘, 会戦.</div><div class=\"def\"><num>③</num> 争い, 闘争.</div><div class=\"def\"><num>④</num> (<i>pl</i>)軍隊.</div>\r\n","<div class=\"hw\">bellus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> かわいい, きれいな, 上品な.</div><div class=\"def\"><num>②</num> すばらしい, みごとな.</div>\r\n","<div class=\"hw\">bellāria</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[bellus]</div><div class=\"def\">(食後の)デザート.</div>\r\n","<div class=\"hw\">bellārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bellum]</div><div class=\"def\">戦争に役立つもの.</div>\r\n","<div class=\"hw\">bellātor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[bello]</div><div class=\"def\">軍人, 戦士.</div><hr><div class=\"hw\">bellātor<SUP>2</SUP></div><div class=\"pos\">-ōris, <i>adj</i></div><div class=\"def\">戦争の;勇敢な, 好戦的な.</div>\r\n","<div class=\"hw\">bellātrix<SUP>1</SUP></div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[bellator<SUP>1</SUP>]</div><div class=\"def\">女戦士.</div><hr><div class=\"hw\">bellātrix<SUP>2</SUP></div><div class=\"pos\">-īcis, <i>adj f</i></div><div class=\"def\">戦争の;好戦的な.</div>\r\n","<div class=\"hw\">bellātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellator]</div><div class=\"def\">戦争の;好戦的な, 勇敢な.</div>\r\n","<div class=\"hw\">bellē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[bellus]</div><div class=\"def\">よく, りっぱに, 好ましく</div><div class=\"ex\"><i>(se)～ habere</i><span class=\"ext\">健康である.</span></div>\r\n","<div class=\"hw\">bellō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[bellum]</div><div class=\"def\">戦争をする;争う, 闘う 〈cum alqo;adversus alqm;pro alqo;inter se〉.</div>\r\n","<div class=\"hw\">Bellōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[bellum]</div><div class=\"def\">〘神話〙ベッローナ《戦の女神;軍神 Mars の妹とも妻ともいう》.</div>\r\n","<div class=\"hw\">bellōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bellum]</div><div class=\"def\">好戦的な.</div>\r\n","<div class=\"hw\">beloacos, belotocos</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙ハナハッカの類(=<a href=\"entry://dictamnus\">dictamnus</a>).</div>\r\n","<div class=\"hw\">belonē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙ダツ, ヨウジウオ(=<a href=\"entry://acus\">acus<SUP>3</SUP></a>).</div>\r\n","<div class=\"hw\">Bendidīus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bendis の.</div>\r\n","<div class=\"hw\">Bendīs</div><div class=\"pos\">-īdis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ベンディース《Thracia の月の女神》.</div>\r\n","<div class=\"hw\">bene</div><div class=\"pos\"><i>adv</i>(<i>comp</i> melius, <i>superl</i> optimē)</div><div class=\"def\"><num>①</num> よく, 申し分なく</div><div class=\"ex\"><i>～ est [habet]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">うまくいっている, いい調子だ</span></div><div class=\"ex\"><i>alci re ～ esse</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ある人にあるものがふんだんにある</span></div><div class=\"ex\"><i>～ te [tibi]</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(乾杯のことば)あなたの健康を祝して.</span></div><div class=\"def\"><num>②</num> 適当に, 適切に.</div><div class=\"def\"><num>③</num> 正しく</div><div class=\"ex\"><i>～ facta</i> (<author>E<small>NN</small></author>)<span class=\"ext\">善行.</span></div><div class=\"def\"><num>④</num> 好意的に</div><div class=\"ex\"><i>alci ～ dicere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人のことをほめる</span></div><div class=\"ex\"><i>～ facis</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">あなた(のご親切)に感謝します, ありがとう.</span></div><div class=\"def\"><num>⑤</num> 快く.</div><div class=\"def\"><num>⑥</num> 有利に, 都合よく.</div><div class=\"def\"><num>⑦</num> 大いに, 十分に, 全く.</div>\r\n","<div class=\"hw\">benedictiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://benedīcō\">benedīcō</a>]</div><div class=\"def\"><num>①</num> 賛美.</div><div class=\"def\"><num>②</num> 聖別された物.</div><div class=\"def\"><num>③</num> 祝福.</div><div class=\"def\"><num>④</num> 〘カト〙聖別(式), (聖体)降福式.</div>\r\n","<div class=\"hw\">benedictum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[benedico]</div><div class=\"def\">祝福.</div>\r\n","<div class=\"hw\">benedictus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://benedīcō\">benedico</a>.</div>\r\n","<div class=\"hw\">benedicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[benedico]</div><div class=\"def\">愛情に満ちた.</div>\r\n","<div class=\"hw\">benedicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[benedicus]</div><div class=\"def\">親切なことばで.</div>\r\n","<div class=\"hw\">benedixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://benedīcō\">benedico</a>.</div>\r\n","<div class=\"hw\">benedīcibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://benedīcō\">benedīcō</a>]</div><div class=\"def\">祝福する.</div>\r\n","<div class=\"hw\">benedīcō</div><div class=\"pos\">-ere -dixī -dictum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[bene/dico<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> よく言う, ほめる 〈+<i>dat</i> [<i>acc</i>]〉.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 聖別する, 清める 〈+<i>dat</i> [<i>acc</i>]〉.</div>\r\n","<div class=\"hw\">benefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://benefaciō\">benefacio</a>.</div>\r\n","<div class=\"hw\">benefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 正しく行なう 〈alqd〉.</div><div class=\"def\"><num>②</num> 親切にする 〈alci〉.</div>\r\n","<div class=\"hw\">benefactiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://benefaciō\">benefaciō</a>]</div><div class=\"def\">善行をなすこと.</div>\r\n","<div class=\"hw\">benefactor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[benefacio]</div><div class=\"def\">恩恵を施す人, 善行者.</div>\r\n","<div class=\"hw\">benefactrix</div><div class=\"pos\">-trīcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://benefactor\">benefactor</a>]</div><div class=\"def\">(女性の)善行者.</div>\r\n","<div class=\"hw\">benefactum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://benefactus\">benefactus</a>]</div><div class=\"def\">(通例 <i>pl</i>)親切, 善行.</div>\r\n","<div class=\"hw\">benefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://benefaciō\">benefacio</a>.</div>\r\n","<div class=\"hw\">beneficentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[beneficus]</div><div class=\"def\">慈善, 恩恵, 善行.</div>\r\n","<div class=\"hw\">beneficientia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://beneficentia\">beneficentia</a>.</div>\r\n","<div class=\"hw\">beneficiolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://beneficium\">beneficium</a>]</div><div class=\"def\">親切, 好意, 恩恵.</div>\r\n","<div class=\"hw\">beneficium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[beneficus]</div><div class=\"def\"><num>①</num> 善行, 親切, 恩恵, 好意</div><div class=\"ex\"><i>beneficio alcis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人のおかげで</span></div><div class=\"ex\"><i>alqm beneficio adficere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に恩恵を施す.</span></div><div class=\"def\"><num>②</num> 愛顧, 支援, 昇進</div><div class=\"ex\">～ <i>populi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">市民の支持.</span></div><div class=\"def\"><num>③</num> 特権</div><div class=\"ex\"><i>vacatio beneficio liberorum</i> (<author>S<small>UET</small></author>)<span class=\"ext\">子持ちの恩典による役目の免除.</span></div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 聖職禄.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘法〙利益</div><div class=\"ex\"><i>～ inventarii</i><span class=\"ext\">(相続財産)目録作成の利益</span></div><div class=\"ex\"><i>～ separationis</i><span class=\"ext\">(相続財産)分離の利益.</span></div>\r\n","<div class=\"hw\">beneficiālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[beneficium]</div><div class=\"def\">情け深い.</div>\r\n","<div class=\"hw\">beneficiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[beneficium]</div><div class=\"def\">恩恵の.</div><hr><div class=\"hw\">beneficiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">雑役を免除された兵士.</div>\r\n","<div class=\"hw\">beneficiātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">《碑》beneficiarius<SUP>2</SUP> であること.</div>\r\n","<div class=\"hw\">beneficus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bene/facio]</div><div class=\"def\">恩恵を施す, 親切な, 慈悲深い.</div>\r\n","<div class=\"hw\">beneficē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[beneficus]</div><div class=\"def\">情け深く, 親切に.</div>\r\n","<div class=\"hw\">beneficō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i>, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">=<a href=\"entry://benefaciō\">benefacio</a>.</div>\r\n","<div class=\"hw\">benefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://benefaciō\">benefacio</a>.</div>\r\n","<div class=\"hw\">beneplaceō</div><div class=\"pos\">-ēre -placuī -placitum, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[bene/placeo]</div><div class=\"def\">...の気に入る, 非常に喜ばれる.</div>\r\n","<div class=\"hw\">beneplacitum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i>(<i>pp</i>)</div><div class=\"ori\">[↑<a href=\"entry://beneplaceō\">beneplaceō</a>]</div><div class=\"def\">気に入ること, 好み.</div>\r\n","<div class=\"hw\">benesuādus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bene/suadeo]</div><div class=\"def\">よい助言をする.</div>\r\n","<div class=\"hw\">Beneventum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ベネウェントゥム《Samnium の町;現 Benevento》.</div>\r\n","<div class=\"hw\">Beneventānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Beneventum の.</div><div class=\"hw2\"><b>Beneventānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Beneventum の住民.</div>\r\n","<div class=\"hw\">benevolens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\">=<a href=\"entry://benevolus\">benevolus<SUP>1</SUP></a>.</div><hr><div class=\"hw\">benevolens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i>, <i>f</i></div><div class=\"def\">好意を寄せる人, 友人.</div>\r\n","<div class=\"hw\">benevolenter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[benevolens<SUP>1</SUP>]</div><div class=\"def\">親切に.</div>\r\n","<div class=\"hw\">benevolentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[benevolens<SUP>1</SUP>]</div><div class=\"def\">好意, 親切;慈悲, 寛大 〈erga [in] alqm〉.</div>\r\n","<div class=\"hw\">benevolus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bene/volo<SUP>2</SUP>]</div><div class=\"def\">善意の, 好意的な, 親切な 〈alci〉.</div><hr><div class=\"hw\">benevolus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://benevolens\">benevolens<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">benevolē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[benevolus<SUP>1</SUP>]</div><div class=\"def\">親切に, 好意をもって.</div>\r\n","<div class=\"hw\">benigniter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[benignus]</div><div class=\"def\">親切に, 好意的に.</div>\r\n","<div class=\"hw\">benignitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[benignus]</div><div class=\"def\"><num>①</num> 好意, 親切.</div><div class=\"def\"><num>②</num> 寛大, 気前のよさ 〈in alqm〉.</div>\r\n","<div class=\"hw\">benignor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://benignus\">benignus</a>]</div><div class=\"def\">喜ぶ 〈in re〉.</div>\r\n","<div class=\"hw\">benignus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bene/gigno]</div><div class=\"def\"><num>①</num> 好意ある, 親切な.</div><div class=\"def\"><num>②</num> 寛大な, 気前のよい.</div><div class=\"def\"><num>③</num> 豊富な, たっぷりの</div><div class=\"ex\"><i>ager</i> ～ (<author>O<small>V</small></author>)<span class=\"ext\">実り豊かな土地.</span></div>\r\n","<div class=\"hw\">benignē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[benignus]</div><div class=\"def\"><num>①</num> 好意をもって, 親切に;情け深く</div><div class=\"ex\">～ <i>dicis</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ご親切に, ありがとう.</span></div><div class=\"def\"><num>②</num> 気前よく, 惜しみなく</div><div class=\"ex\"><i>～ facere alci</i> (<author>T<small>ER</small></author>)<span class=\"ext\">ある人に恩恵を与える.</span></div>\r\n","<div class=\"hw\">benivol-</div><div class=\"def\">⇒benevol-.</div>\r\n","<div class=\"hw\">benna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">荷車の一種.</div>\r\n","<div class=\"hw\">benzidīnum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ベンジジン.</div>\r\n","<div class=\"hw\">benzinum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ベンジン.</div>\r\n","<div class=\"hw\">benzolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ベンゾール.</div>\r\n","<div class=\"hw\">berberidāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙メギ科.</div>\r\n","<div class=\"hw\">berbex</div><div class=\"pos\">-ēcis, <i>m</i></div><div class=\"def\">=<a href=\"entry://vervex\">vervex</a>.</div>\r\n","<div class=\"hw\">Berecyntae</div><div class=\"pos\">-ārum, <B>-es</B> -um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベレキュンタエ, <SUP>*</SUP>-タイ《Phrygia にいた一部族》.</div>\r\n","<div class=\"hw\">Berecynt(h)ius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Berecyntus の</div><div class=\"ex\"><i>Berecyntia mater</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Cybelē\">Cybele</a></span></div><div class=\"ex\"><i>～ heros</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Cybelē\">Cybele</a> の息子 <a href=\"entry://Midās\">Midas</a>.</span></div>\r\n","<div class=\"hw\">Berecyntus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベレキュントゥス, <SUP>*</SUP>-トス《Cybele に捧げられた Phrygia の山》.</div>\r\n","<div class=\"hw\">Berenīcis</div><div class=\"pos\">-idos, <i>f</i></div><div class=\"def\">ベレニーキス《Berenice(2a)周辺の地域》.</div>\r\n","<div class=\"hw\">Berenīcē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベレニーケー《 (1) 女性名;特に (a) Judaea 王 Agrippa I の娘.(b) エジプト王 Ptolemaeus III Euergetes の妻;夫のためにささげた髪の毛が星座 crinis Berenices になったという.(2) 都市名; (a) Cyrenaica 西端の町;現 Benghazi.(b) エジプト南東部の紅海沿岸の町》.</div>\r\n","<div class=\"hw\">Berenīcēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Berenice の.</div>\r\n","<div class=\"hw\">Bergomum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ベルゴムム《Gallia Transpadana の町;現 Bergamo》.</div>\r\n","<div class=\"hw\">Beroea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベロエア, <SUP>*</SUP>ベロイア《Macedonia の町;現 Véroia》.</div>\r\n","<div class=\"hw\">Beroeaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Beroea の.</div>\r\n","<div class=\"hw\">Beroeensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Beroea の住民.</div>\r\n","<div class=\"hw\">Beroē</div><div class=\"pos\">-es, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ベロエー《Semele の乳母》.</div>\r\n","<div class=\"hw\">beroīdea</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘動〙ウリクラゲ目.</div>\r\n","<div class=\"hw\">berula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙アブラナ科の植物.</div>\r\n","<div class=\"hw\">Bessicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bessi 族の.</div>\r\n","<div class=\"hw\">bessālis, bēsālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bēs\">bēs</a>]</div><div class=\"def\">3分の2の.</div>\r\n","<div class=\"hw\">Bessī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベッシー, <SUP>*</SUP>ベッソイ《Thracia の一部族》.</div>\r\n","<div class=\"hw\">bestia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 獣.</div><div class=\"def\"><num>②</num> (円形競技場で用いられる)猛獣.</div><div class=\"def\"><num>③</num> (軽蔑的に)人でなし, 畜生.</div><div class=\"def\"><num>④</num> (B-)〘天〙狼座.</div>\r\n","<div class=\"hw\">bestiola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[bestia]</div><div class=\"def\">小さな生物, 虫.</div>\r\n","<div class=\"hw\">bestiālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bestia\">bestia</a>]</div><div class=\"def\">獣の(ような).</div>\r\n","<div class=\"hw\">bestiāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[bestialis]</div><div class=\"def\">獣のように.</div>\r\n","<div class=\"hw\">bestiālitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://bestiālis\">bestiālis</a>]</div><div class=\"def\">獣性.</div>\r\n","<div class=\"hw\">bestiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bestia]</div><div class=\"def\">獣の</div><div class=\"ex\"><i>ludus ～</i> (<author>S<small>EN</small></author>)<span class=\"ext\">(円形競技場で)野獣と戦うこと.</span></div><hr><div class=\"hw\">bestiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(見せ物として)野獣と戦う者.</div>\r\n","<div class=\"hw\">Bethle(h)em</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">ベトレヘム, <SUP>∥</SUP>ベツレヘム《Palaestina 中部の町;Iesus の生地》.</div>\r\n","<div class=\"hw\">betula, -lla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙カバノキ.</div>\r\n","<div class=\"hw\">betulāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙カバノキ科.</div>\r\n","<div class=\"hw\">beābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[beo]</div><div class=\"def\">祝福された.</div>\r\n","<div class=\"hw\">beātificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[beatus/facio]</div><div class=\"def\">幸福にする.</div>\r\n","<div class=\"hw\">beātificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[beatifico]</div><div class=\"def\"><num>①</num> 幸福.</div><div class=\"def\"><num>②</num> 〘カト〙列福(式).</div>\r\n","<div class=\"hw\">beātificātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://beātificō\">beātificō</a>]</div><div class=\"def\">幸福にしてくれる人.</div>\r\n","<div class=\"hw\">beātificō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[beatus/facio]</div><div class=\"def\">幸福にする, 祝福する.</div>\r\n","<div class=\"hw\">beātitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[beatus]</div><div class=\"def\">幸福, 至福.</div>\r\n","<div class=\"hw\">beātitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">=<a href=\"entry://beātitās\">beatitas</a>.</div>\r\n","<div class=\"hw\">beātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://beātus\">beātus</a>]</div><div class=\"def\">=<a href=\"entry://beātitās\">beatitas</a>.</div>\r\n","<div class=\"hw\">beātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[beo]</div><div class=\"def\">幸福な, 祝福された, 恵まれた.</div>\r\n","<div class=\"hw\">beātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[beatus]</div><div class=\"def\">幸福に.</div>\r\n","<div class=\"hw\">beō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">幸福にする, 喜ばせる, 祝福する, 豊かにする 〈alqm re〉</div><div class=\"ex\"><i>munere te parvo beare</i> (<author>H<small>OR</small></author>)<span class=\"ext\">小さな贈り物であなたを喜ばせる.</span></div>\r\n","<div class=\"hw\">bi-</div><div class=\"pos\"><i>pref</i></div><div class=\"def\">「二」 「重」 などの意.</div>\r\n","<div class=\"hw\">biarchia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">biarchus の職.</div>\r\n","<div class=\"hw\">biarchus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">糧食管理官.</div>\r\n","<div class=\"hw\">bibaria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">酒場.</div>\r\n","<div class=\"hw\">bibax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">酒飲みの.</div>\r\n","<div class=\"hw\">Biberius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">(「大酒飲み」 の意)Tiberius 帝のあだ名.</div>\r\n","<div class=\"hw\">biberārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">酒売り.</div>\r\n","<div class=\"hw\">Bibesia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">酒飲みの国《Plautus の造語》.</div>\r\n","<div class=\"hw\">bibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bibo]</div><div class=\"def\">飲用に適する.</div>\r\n","<div class=\"hw\">biblia</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i>, <B>-ia</B> -ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">本, 書籍</div><div class=\"ex\"><i>～ sacra</i><span class=\"ext\">聖書.</span></div>\r\n","<div class=\"hw\">biblicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://biblia\">biblia</a>]</div><div class=\"def\">聖書の.</div>\r\n","<div class=\"hw\">bibliographia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">書誌学.</div>\r\n","<div class=\"hw\">bibliographus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">書誌学者.</div>\r\n","<div class=\"hw\">bibliopōla</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">本屋, 書店.</div>\r\n","<div class=\"hw\">bibliothēca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 書架, 本棚.</div><div class=\"def\"><num>②</num> 図書室, 図書館.</div><div class=\"def\"><num>③</num> 蔵書.</div>\r\n","<div class=\"hw\">bibliothēcula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[bibliotheca]</div><div class=\"def\">小文庫.</div>\r\n","<div class=\"hw\">bibliothēcālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bibliothēca\">bibliothēca</a>]</div><div class=\"def\">蔵書の.</div>\r\n","<div class=\"hw\">bibliothēcārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bibliotheca]</div><div class=\"def\">司書, 図書館員.</div>\r\n","<div class=\"hw\">Bibracte</div><div class=\"pos\">-is, <i>n</i></div><div class=\"def\">ビブラクテ《Gallia 中部にあった Aedui 族の首都;現 Mont-Beuvray》.</div>\r\n","<div class=\"hw\">Bibrax</div><div class=\"pos\">-actis, <i>f</i></div><div class=\"def\">ビブラクス《Gallia の Remi 族の町》.</div>\r\n","<div class=\"hw\">Bibrocī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ビブロキー《Britannia にいた一部族》.</div>\r\n","<div class=\"hw\">bibulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bibo]</div><div class=\"def\"><num>①</num> しきりに飲みたがる 〈alcis rei〉.</div><div class=\"def\"><num>②</num> しきりに聞きたがる.</div><div class=\"def\"><num>③</num> 吸収する</div><div class=\"ex\"><i>charta bibula</i> (<author>P<small>LIN</small> M<small>IN</small></author>)<span class=\"ext\">吸取り紙.</span></div><div class=\"def\"><num>④</num> 飲用に適する.</div>\r\n","<div class=\"hw\">Bibulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ビブルス《ローマ人の家名;特に <i>M. Calpurnius ～</i>, Caesar の同僚執政官(前59)》.</div>\r\n","<div class=\"hw\">Bibāculus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ビバークルス《ローマ人の家名》.</div>\r\n","<div class=\"hw\">bibī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://bibō\">bibo</a>.</div>\r\n","<div class=\"hw\">bibō</div><div class=\"pos\">-ere bibī bibitum, <i>tr</i>(<i>intr</i>)</div><div class=\"def\"><num>①</num> 飲む</div><div class=\"ex\"><i>bibere Tiberim</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Tiberis 川のほとりで暮らす</span></div><div class=\"ex\"><i>bibere aequoreas aquas</i> (<author>O<small>V</small></author>)<span class=\"ext\">難船しておぼれる.</span></div><div class=\"def\"><num>②</num> 吸い込む, 吸収する</div><div class=\"ex\"><i>bibere aure alqd</i> (<author>H<small>OR</small></author>)<span class=\"ext\">あることに熱心に耳を傾ける.</span></div>\r\n","<div class=\"hw\">bicapitis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://biceps\">biceps</a>.</div>\r\n","<div class=\"hw\">bicapitus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://biceps\">biceps</a>.</div>\r\n","<div class=\"hw\">biceps</div><div class=\"pos\">-cipitis, <i>adj</i></div><div class=\"ori\">[bi-/caput]</div><div class=\"def\"><num>①</num> 二つの頭をもった, 両面の</div><div class=\"ex\"><i>～ argumentum</i> (<author>A<small>PUL</small></author>)<span class=\"ext\">〘論〙両刀論法, ジレンマ</span></div><div class=\"ex\"><i>Parnasus ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">二つの峰をもつ Parnasus 山</span></div><div class=\"ex\"><i>gladius</i> ～ (<author>V<small>ULG</small></author>)<span class=\"ext\">諸刃の剣.</span></div><div class=\"def\"><num>②</num> 二つに分かれた.</div>\r\n","<div class=\"hw\">biclīnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">二人用の食事用臥台.</div>\r\n","<div class=\"hw\">bicolor</div><div class=\"pos\">-ōris, <i>adj</i></div><div class=\"ori\">[bi-/color]</div><div class=\"def\">2色の.</div>\r\n","<div class=\"hw\">Bicorniger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[bi-/corniger]</div><div class=\"def\">2本の角<SUB>つの</SUB>をもった《Bacchus の添え名の一つ》.</div>\r\n","<div class=\"hw\">bicornis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/cornu]</div><div class=\"def\">2本の角<SUB>つの</SUB>をもった</div><div class=\"ex\"><i>furea</i> ～ (<author>V<small>ERG</small></author>)<span class=\"ext\">二叉の支柱</span></div><div class=\"ex\"><i>bicorne jugum</i> (<author>S<small>TAT</small></author>)<span class=\"ext\">=<a href=\"entry://Parnāsus\">Parnasus</a>.</span></div>\r\n","<div class=\"hw\">bicorpor</div><div class=\"pos\">-oris, <i>adj</i></div><div class=\"ori\">[bi-/corpus]</div><div class=\"def\">二つの体をもった.</div>\r\n","<div class=\"hw\">bicubitālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/cubitum]</div><div class=\"def\">2腕尺(=約1<i>m</i>)の.</div>\r\n","<div class=\"hw\">bicuspidālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/cuspis]</div><div class=\"def\">〘解〙二尖の, 両尖の.</div>\r\n","<div class=\"hw\">bidens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[bi-/dens]</div><div class=\"def\"><num>①</num> 二つの歯をもった.</div><div class=\"def\"><num>②</num> 二叉の</div><div class=\"ex\"><i>forfex</i> ～ (<author>V<small>ERG</small></author>)<span class=\"ext\">2枚刃のはさみ.</span></div><hr><div class=\"hw\">bidens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i>, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://bidens\">bidens<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> (<i>m</i>)二叉の鍬<SUB>くわ</SUB>.</div><div class=\"def\"><num>②</num> (<i>f</i>)(歯が上下とも完全に生えそろった)犠牲獣(特に羊).</div>\r\n","<div class=\"hw\">bidental</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://bidens\">bidens<SUP>2</SUP></a>]</div><div class=\"def\">落雷のあった場所《その場を聖域として囲み, 羊を犠牲にささげた》;(そこでささげられる)いけにえ.</div>\r\n","<div class=\"hw\">bidentālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bidental\">bidental</a>]</div><div class=\"def\">《碑》落雷のあった場所の;(そこでささげられる)いけにえの.</div>\r\n","<div class=\"hw\">Bidis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">ビディス《Sicilia 島の町》.</div>\r\n","<div class=\"hw\">Bidīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bidis の.</div>\r\n","<div class=\"hw\">biennis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://biennium\">biennium</a>]</div><div class=\"def\">2年間の.</div>\r\n","<div class=\"hw\">biennium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bi-/annus]</div><div class=\"def\">2年間.</div>\r\n","<div class=\"hw\">biennālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[biennium]</div><div class=\"def\">2年間の.</div>\r\n","<div class=\"hw\">bifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[bi-/fero]</div><div class=\"def\">(年に)2度実がなる.</div>\r\n","<div class=\"hw\">biferus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/ferus]</div><div class=\"def\">二種の動物から成る, 異成分から成る.</div>\r\n","<div class=\"hw\">bifidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/findo]</div><div class=\"def\">二つに分かれた, 二叉の.</div>\r\n","<div class=\"hw\">bifidātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://bifidus\">bifidus</a>.</div>\r\n","<div class=\"hw\">biforis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/foris<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (戸・窓が)両開きの, 折り戸の.</div><div class=\"def\"><num>②</num> 穴が二つある.</div>\r\n","<div class=\"hw\">biformis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/forma]</div><div class=\"def\">二つの姿[形]をもった.</div>\r\n","<div class=\"hw\">biformātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://biformis\">biformis</a>.</div>\r\n","<div class=\"hw\">biforus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://biforis\">biforis</a>.</div>\r\n","<div class=\"hw\">bifrons</div><div class=\"pos\">-ontis, <i>adj</i></div><div class=\"ori\">[bi-/frons<SUP>2</SUP>]</div><div class=\"def\">二つの顔をもった《Janus の添え名》.</div>\r\n","<div class=\"hw\">bifurcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/furca]</div><div class=\"def\">二叉の.</div>\r\n","<div class=\"hw\">bifurcātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[bifurcus]</div><div class=\"def\">〘解〙分岐.</div>\r\n","<div class=\"hw\">bifurcātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://bifurcus\">bifurcus</a>]</div><div class=\"def\">〘解〙分岐の.</div>\r\n","<div class=\"hw\">bifāriam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">二様に, 二重に.</div>\r\n","<div class=\"hw\">bifārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">二様の, 二重の.</div>\r\n","<div class=\"hw\">bifāriē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://bifāriam\">bifariam</a>.</div>\r\n","<div class=\"hw\">bifīlum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[bi-/filum]</div><div class=\"def\">二重の糸.</div>\r\n","<div class=\"hw\">bigamia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://bigamus\">bigamus<SUP>1</SUP></a>]</div><div class=\"def\">重婚(罪), 二重結婚.</div>\r\n","<div class=\"hw\">bigamus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">重婚した.</div><hr><div class=\"hw\">bigamus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">重婚者.</div>\r\n","<div class=\"hw\">bigeminus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/geminus]</div><div class=\"def\">二重の.</div>\r\n","<div class=\"hw\">bigener</div><div class=\"pos\">-nera -nerum, <i>adj</i></div><div class=\"ori\">[bi-/genus<SUP>1</SUP>]</div><div class=\"def\">異なる種族間に生まれた, 混血の, 雑種の.</div>\r\n","<div class=\"hw\">Bigerra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ビゲッラ《Hispania Tarraconensis 南部の町;現 Bogara》.</div>\r\n","<div class=\"hw\">Bigerriōnes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ビゲッリオーネス《Aquitania にいた一部族》.</div>\r\n","<div class=\"hw\">bignae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[bi-/gigno]</div><div class=\"def\">(女性の)双生児.</div>\r\n","<div class=\"hw\">bignoniāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ノウゼンカズラ科.</div>\r\n","<div class=\"hw\">bijugis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://bijugus\">bijugus</a>.</div>\r\n","<div class=\"hw\">bijugus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/jugis<SUP>2</SUP>]</div><div class=\"def\">二頭立ての.</div>\r\n","<div class=\"hw\">bijugī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[bijugus]</div><div class=\"def\">(<i>sc. </i> equi)=<a href=\"entry://bīgae\">bigae</a>.</div>\r\n","<div class=\"hw\">bilanx<SUP>1</SUP></div><div class=\"pos\">-lancis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/lanx]</div><div class=\"def\">(天秤が)二枚皿の.</div><hr><div class=\"hw\">bilanx<SUP>2</SUP></div><div class=\"pos\">-lancis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">(二枚皿の)天秤.</div>\r\n","<div class=\"hw\">bilaterālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/lateralis]</div><div class=\"def\"><num>①</num> 〘生物〙両側性の, 左右相称の.</div><div class=\"def\"><num>②</num> 〘解・病〙両側(性)の.</div><div class=\"def\"><num>③</num> 〘法〙双務的な.</div>\r\n","<div class=\"hw\">Bilbilis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">ビルビリス《Hispania Tarraconensis の町;詩人 Martialis の生地》.</div>\r\n","<div class=\"hw\">bilinguis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/lingua]</div><div class=\"def\"><num>①</num> 2枚の舌をもった.</div><div class=\"def\"><num>②</num> 2言語を用いる.</div><div class=\"def\"><num>③</num> うそつきの, 二枚舌の.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 二重の意味をもった;寓意的な.</div>\r\n","<div class=\"hw\">bilix</div><div class=\"pos\">-līcis, <i>adj</i></div><div class=\"ori\">[bi-/licium]</div><div class=\"def\">二本糸の, 二重織りの.</div>\r\n","<div class=\"hw\">bilongus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/longus]</div><div class=\"def\">2倍の長さの</div><div class=\"ex\"><i>pes ～</i><span class=\"ext\">〘詩〙2個の長音節から成る詩脚.</span></div>\r\n","<div class=\"hw\">bilustris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/lustrum<SUP>2</SUP>]</div><div class=\"def\">2 lustra(=10年間)の.</div>\r\n","<div class=\"hw\">bilychnis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/lychnus]</div><div class=\"def\">二つの灯心をもった.</div>\r\n","<div class=\"hw\">bilībra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[bi-/libra]</div><div class=\"def\">2ポンド.</div>\r\n","<div class=\"hw\">bilībris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bilībra\">bilībra</a>]</div><div class=\"def\"><num>①</num> 重さが2ポンドの.</div><div class=\"def\"><num>②</num> 2ポンドはいる.</div>\r\n","<div class=\"hw\">bimammius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/mamma]</div><div class=\"def\">(ブドウが)二つの房をもっている.</div>\r\n","<div class=\"hw\">bimaris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/mare]</div><div class=\"def\">二つの海の間に位置する.</div>\r\n","<div class=\"hw\">bimarītus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bi-/maritus<SUP>1</SUP>]</div><div class=\"def\">二人の妻をもつ夫, 重婚者.</div>\r\n","<div class=\"hw\">bimembris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/membrum]</div><div class=\"def\">2種類の手足をもった(=半人半獣の).</div>\r\n","<div class=\"hw\">bimembrēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://bimembris\">bimembris</a>]</div><div class=\"def\">=<a href=\"entry://Centaurus\">Centaurus</a> 族.</div>\r\n","<div class=\"hw\">bime(n)stris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/mensis]</div><div class=\"def\">2か月の.</div>\r\n","<div class=\"hw\">bimenstruus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/mensis]</div><div class=\"def\">2か月の.</div>\r\n","<div class=\"hw\">bimāter</div><div class=\"pos\">-tris, <i>adj</i></div><div class=\"ori\">[bi-/mater]</div><div class=\"def\">二人の母をもつ《Bacchus の添え名の一つ》.</div>\r\n","<div class=\"hw\">Bingium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ビンギウム《Rhenus 河畔にあった Gallia の町》.</div>\r\n","<div class=\"hw\">binoctium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bi-/nox]</div><div class=\"def\">二夜.</div>\r\n","<div class=\"hw\">binōminis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/nomen]</div><div class=\"def\">二つの名前をもった.</div>\r\n","<div class=\"hw\">binūbus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[bi-/nubo]</div><div class=\"def\">重婚者.</div>\r\n","<div class=\"hw\">biocōlȳta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">不法行為を取り締まる人.</div>\r\n","<div class=\"hw\">biogenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙生物発生.</div>\r\n","<div class=\"hw\">biographia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">伝記;伝記文学.</div>\r\n","<div class=\"hw\">biologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">生物学.</div>\r\n","<div class=\"hw\">bios</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギリシア産ワインの一種《「生命」 の意》.</div>\r\n","<div class=\"hw\">bipalmis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/palmus]</div><div class=\"def\">2掌尺<SUB>しょうしゃく</SUB>の.</div>\r\n","<div class=\"hw\">bipartiō</div><div class=\"pos\">-īre -īvī -ītum, <i>tr</i></div><div class=\"ori\">[bi-/partio<SUP>2</SUP>]</div><div class=\"def\">二つに分ける.</div>\r\n","<div class=\"hw\">bipartītiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[bipartio]</div><div class=\"def\">二つに分けること, 二分割.</div>\r\n","<div class=\"hw\">bipartītus</div><div class=\"pos\">-a -um, <i>adj(pp)</i></div><div class=\"ori\">[bipartio]</div><div class=\"def\">二つに分かれた.</div>\r\n","<div class=\"hw\">bipartītē</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://bipartītō\">bipartito</a>.</div>\r\n","<div class=\"hw\">bipartītō</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://bipartītus\">bipartītus</a>]</div><div class=\"def\">二つに分かれて.</div>\r\n","<div class=\"hw\">bipatens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[bi-/pateo]</div><div class=\"def\">両開きの;扉が二つある.</div>\r\n","<div class=\"hw\">bipedālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/pes]</div><div class=\"def\">2足尺[フィート]の.</div>\r\n","<div class=\"hw\">bipedāneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/pes]</div><div class=\"def\">2足尺[フィート]の.</div>\r\n","<div class=\"hw\">bipennifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://bipennis\">bipennis<SUP>1</SUP></a>/fero]</div><div class=\"def\">両刃の斧を持っている.</div>\r\n","<div class=\"hw\">bipennis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/penna]</div><div class=\"def\"><num>①</num> 二つの翼をもった.</div><div class=\"def\"><num>②</num> (斧が)両刃の.</div><hr><div class=\"hw\">bipennis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">両刃の斧.</div>\r\n","<div class=\"hw\">bipennātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/penna]</div><div class=\"def\">〘解〙双翼状の.</div>\r\n","<div class=\"hw\">bipert-</div><div class=\"def\">⇒bipart-.</div>\r\n","<div class=\"hw\">bipālium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bi-/pala]</div><div class=\"def\">踏み棒付きシャベル.</div>\r\n","<div class=\"hw\">bipēs<SUP>1</SUP></div><div class=\"pos\">-pedis, <i>adj</i></div><div class=\"ori\">[bi-/pes]</div><div class=\"def\">二本足の.</div><hr><div class=\"hw\">bipēs<SUP>2</SUP></div><div class=\"pos\">-pedis, <i>m</i></div><div class=\"def\">二本足の動物(=軽蔑的に, 人間).</div>\r\n","<div class=\"hw\">birrettum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 〘カト〙ビレッタ《聖職者用の角帽》.</div><div class=\"def\"><num>②</num> ベレー帽.</div>\r\n","<div class=\"hw\">birrus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">フード付きの短いマント.</div>\r\n","<div class=\"hw\">birēmis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/remus]</div><div class=\"def\">2本オールの;二段橈の.</div><hr><div class=\"hw\">birēmis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">2本オールの小舟;二段橈船.</div>\r\n","<div class=\"hw\">bis</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 2度, 2回</div><div class=\"ex\">～ <i>terve</i> (<author>C<small>IC</small></author>)<span class=\"ext\">2, 3度</span></div><div class=\"ex\">～<i>terque</i> (<author>M<small>ART</small></author>)<span class=\"ext\">たびたび</span></div><div class=\"ex\"><i>～ ad eundum</i>(sc. <i>lapidem offendi</i>)(<author>C<small>IC</small></author>)<span class=\"ext\">2度同じ(石)に(つまずく)《「みっともない」という意の格言》.</span></div><div class=\"def\"><num>②</num> 二重に, 2倍に</div><div class=\"ex\"><i>～ tanto [tantum]</i> (<author>P<small>LAUT</small> [V<small>ERG</small>]</author>)<span class=\"ext\">2倍大きく</span></div><div class=\"ex\"><i>～ octonis annis</i> (<author>O<small>V</small></author>)<span class=\"ext\">16才の.</span></div>\r\n","<div class=\"hw\">Bisanthē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビサンテー《Propontis 海に面する Thracia の町》.</div>\r\n","<div class=\"hw\">bisellium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bi-/sella]</div><div class=\"def\">二人分の座席;(特に)特権としての一人だけの貴賓席.</div>\r\n","<div class=\"hw\">bisextum</div><div class=\"pos\">-ī, <i>n</i>, <B>bisextus</B> -ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[bi-/sextus]</div><div class=\"def\">閏日《2月24日の後に置かれた》.</div>\r\n","<div class=\"hw\">bisextīlis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://bisextum\">bisextum</a>]</div><div class=\"def\">閏日のある</div><div class=\"ex\"><i>annus ～</i> (<author>I<small>SID</small></author>)<span class=\"ext\">閏年<SUB>うるうどし</SUB>.</span></div>\r\n","<div class=\"hw\">bismūtum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ビスマス, 蒼鉛<SUB>そうえん</SUB>.</div>\r\n","<div class=\"hw\">bissēnī, bis sēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[sex]</div><div class=\"def\">《詩》12ずつの(=<a href=\"entry://duodēnī\">duodeni</a>).</div>\r\n","<div class=\"hw\">Bistones</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビストネス《Thracia にいた一部族》.</div>\r\n","<div class=\"hw\">Bistonia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビストニア(ー)《Bistones 族の国(=<a href=\"entry://Thrācia\">Thracia</a>)》.</div>\r\n","<div class=\"hw\">Bistonis<SUP>1</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Bistones 族の, Thracia の</div><div class=\"ex\">～<i> ales</i> (<author>S<small>EN</small></author>)<span class=\"ext\">=<a href=\"entry://Procnē\">Procne</a>.</span></div><hr><div class=\"hw\">Bistonis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">Thracia の女(=<a href=\"entry://Baccha\">Baccha</a>).</div>\r\n","<div class=\"hw\">Bistonius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bistones 族の, Thracia の.</div>\r\n","<div class=\"hw\">bisulcis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[bi-/sulcus]</div><div class=\"def\">二つに分かれた, 二叉の</div><div class=\"ex\"><i>～ lingua</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">裂けた舌;二枚舌を使う者.</span></div>\r\n","<div class=\"hw\">bisulcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://bisulcis\">bisulcis</a>.</div>\r\n","<div class=\"hw\">bisyllabus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/syllaba]</div><div class=\"def\">2音節の.</div>\r\n","<div class=\"hw\">bisōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"def\">〘動〙ヤギュウ(野牛), バイソン.</div>\r\n","<div class=\"hw\">Biturīges</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ビトゥリーゲス《 (1) Gallia 中央部にいた一部族;～ Cubi とも呼ばれる.(2) Aquitania にいた一部族;～ Vivisci とも呼ばれる;首都は Burdigala(現 Bordeaux)》.</div>\r\n","<div class=\"hw\">Bitō(n)</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ビトー(ン)《Argos の女神官 Cydippe の息子で Cleobis の兄弟;親孝行で有名》.</div>\r\n","<div class=\"hw\">bitūmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\">瀝青.</div>\r\n","<div class=\"hw\">bitūmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bitūmen\">bitūmen</a>]</div><div class=\"def\">瀝青の.</div>\r\n","<div class=\"hw\">bitūminō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[bitumen]</div><div class=\"def\">瀝青を塗る.</div>\r\n","<div class=\"hw\">bitūminōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bitumen]</div><div class=\"def\">瀝青質の.</div>\r\n","<div class=\"hw\">biventer</div><div class=\"pos\">-tra -trum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bi-/venter]</div><div class=\"def\">〘解〙二腹の.</div>\r\n","<div class=\"hw\">bivertex</div><div class=\"pos\">-ticis, <i>adj</i></div><div class=\"ori\">[bi-/vertex]</div><div class=\"def\">二つの峰[頂上]をもった.</div>\r\n","<div class=\"hw\">bivium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://bivius\">bivius</a>]</div><div class=\"def\"><num>①</num> 交差点, 岐路.</div><div class=\"def\"><num>②</num> 二つの方法[手段].</div>\r\n","<div class=\"hw\">bivius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/via]</div><div class=\"def\">二つの道のある;岐路の.</div>\r\n","<div class=\"hw\">Biās</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビアース《Priene 出身の哲学者(前6世紀);ギリシア七賢人の一人》.</div>\r\n","<div class=\"hw\">Biōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビオーン《 (1) Smyrna 出身のギリシアの田園詩人(前100頃).(2) Scythia 出身の Cyrene 学派の哲学者(前3世紀前半);辛辣な皮肉屋》.</div>\r\n","<div class=\"hw\">Biōnēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bion (2) 風の(=辛辣な, 機知に富んだ).</div>\r\n","<div class=\"hw\">biōticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">日常的な, ありふれた.</div>\r\n","<div class=\"hw\">blachnon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙オシダ.</div>\r\n","<div class=\"hw\">blaesus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">舌たらずに発音する, 口ごもっている.</div>\r\n","<div class=\"hw\">Blandae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ブランダエ《 (1) Lucania の沿岸の町.(2) Hispania Tarraconensis の町》.</div>\r\n","<div class=\"hw\">blandicella</div><div class=\"pos\">-ōrum, <i>n pl dim</i></div><div class=\"ori\">[blandus]</div><div class=\"def\">甘言, お世辞.</div>\r\n","<div class=\"hw\">blandiculē</div><div class=\"pos\"><i>adv dim</i></div><div class=\"ori\">[blande]</div><div class=\"def\">魅力的に.</div>\r\n","<div class=\"hw\">blandidicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[blandus/dico<SUP>2</SUP>]</div><div class=\"def\">甘言を用いる, 口のうまい.</div>\r\n","<div class=\"hw\">blandiloquens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[blandus/loquor]</div><div class=\"def\">口のうまい.</div>\r\n","<div class=\"hw\">blandiloquentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://blandiloquens\">blandiloquens</a>]</div><div class=\"def\">甘言, お世辞.</div>\r\n","<div class=\"hw\">blandiloquentulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"def\">=<a href=\"entry://blandidicus\">blandidicus</a>.</div>\r\n","<div class=\"hw\">blandiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://blandidicus\">blandidicus</a>.</div>\r\n","<div class=\"hw\">blandior</div><div class=\"pos\">-īrī -ītus sum, <i>intr dep</i></div><div class=\"ori\">[blandus]</div><div class=\"def\"><num>①</num> 機嫌を取る, 甘言を用いる, こびへつらう 〈alci〉</div><div class=\"ex\"><i>blandiri sibi</i> (<author>P<small>LIN</small> M<small>IN</small></author>)<span class=\"ext\">思い違いをする.</span></div><div class=\"def\"><num>②</num> 楽しませる, 魅了する 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">blanditer</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://blandē\">blande</a>.</div>\r\n","<div class=\"hw\">blanditia</div><div class=\"pos\">-ae, <B>-tiēs</B> -ēī, <i>f</i></div><div class=\"ori\">[blandus]</div><div class=\"def\"><num>①</num> (特に <i>pl</i>)甘言, お世辞.</div><div class=\"def\"><num>②</num> 魅惑, 魅力, 快適.</div><div class=\"def\"><num>③</num> 美味.</div>\r\n","<div class=\"hw\">blandulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://blandus\">blandus</a>]</div><div class=\"def\">好ましい, 魅力的な.</div>\r\n","<div class=\"hw\">blandus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 機嫌を取る, こびへつらう.</div><div class=\"def\"><num>②</num> 好ましい, 魅力的な.</div>\r\n","<div class=\"hw\">blandē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[blandus]</div><div class=\"def\">ことば巧みに, 誘惑するように.</div>\r\n","<div class=\"hw\">blandīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://blandior\">blandior</a>]</div><div class=\"def\">(通例 <i>pl</i>)</div><div class=\"def\"><num>①</num> 甘言, お世辞.</div><div class=\"def\"><num>②</num> 魅了するもの, 楽しみを与えるもの.</div><div class=\"def\"><num>③</num> 調味料, 薬味.</div><div class=\"def\"><num>④</num> 治療.</div>\r\n","<div class=\"hw\">blandītus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[blandior]</div><div class=\"def\">好ましい, 魅力的な.</div>\r\n","<div class=\"hw\">blasphēmia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i>, <B>-mium</B> -ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">誹謗, 中傷;冒涜.</div>\r\n","<div class=\"hw\">blasphēmus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">そしる, ののしる;冒涜的な.</div>\r\n","<div class=\"hw\">blasphēmābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[blasphemo]</div><div class=\"def\">非難に値する.</div>\r\n","<div class=\"hw\">blasphēmātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[blasphemo]</div><div class=\"def\">誹謗, 中傷.</div>\r\n","<div class=\"hw\">blasphēmō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ののしる, 非難する;冒涜する.</div>\r\n","<div class=\"hw\">blastula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙胞胚.</div>\r\n","<div class=\"hw\">blastēma</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘生物〙芽体.</div>\r\n","<div class=\"hw\">blaterātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://blaterō\">blaterō</a>]</div><div class=\"def\">饒舌, おしゃべり.</div>\r\n","<div class=\"hw\">blaterō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> blatio]</div><div class=\"def\"><num>①</num> ぺちゃくちゃしゃべる.</div><div class=\"def\"><num>②</num> (羊・ラクダ・カエルなどが)鳴く.</div>\r\n","<div class=\"hw\">blatiō</div><div class=\"pos\">-īre, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> blatero]</div><div class=\"def\">ぺちゃくちゃしゃべる.</div>\r\n","<div class=\"hw\">blatta<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘昆〙ゴキブリ・イガなどの昆虫.</div><hr><div class=\"hw\">blatta<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">緋色.</div>\r\n","<div class=\"hw\">blatterō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://blaterō\">blatero</a>.</div>\r\n","<div class=\"hw\">blatteus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[blatta<SUP>2</SUP>]</div><div class=\"def\">緋色の.</div>\r\n","<div class=\"hw\">blattinus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://blatteus\">blatteus</a>.</div>\r\n","<div class=\"hw\">blattāria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘昆〙ゴキブリ目.</div>\r\n","<div class=\"hw\">blattārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[blatta<SUP>1</SUP>]</div><div class=\"def\">ガ(蛾)の</div><div class=\"ex\"><i>balnea blattaria</i> (<author>S<small>EN</small></author>)<span class=\"ext\">薄暗い浴室《蛾が陽光をきらうためにこう言われた》.</span></div>\r\n","<div class=\"hw\">Blaudēnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">大 Phrygia の町 Blaudus の.</div>\r\n","<div class=\"hw\">Blemyes</div><div class=\"pos\">-um, <B>Blem(m)yī</B> -ōrum, <B>-yae</B> -ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブレミュエス《Aethiopia にいた一部族》.</div>\r\n","<div class=\"hw\">blendius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘魚〙イソギンポ.</div>\r\n","<div class=\"hw\">blennorrhoea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙膿漏.</div>\r\n","<div class=\"hw\">blennus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">のろま, ばか者.</div>\r\n","<div class=\"hw\">bliteus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://blitum\">blitum</a>]</div><div class=\"def\">つまらない, 取るに足りない.</div>\r\n","<div class=\"hw\">blitum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ホウレンソウの一種.</div>\r\n","<div class=\"hw\">Blossius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブロッシウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">blēchōn</div><div class=\"pos\">-onis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙野生のメグサハッカ.</div>\r\n","<div class=\"hw\">boa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘動〙大きなヘビ.</div><div class=\"def\"><num>②</num> 〘病〙はしか, 麻疹.</div>\r\n","<div class=\"hw\">bobīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://bovīlis\">bovilis</a>.</div>\r\n","<div class=\"hw\">Bocc(h)ar</div><div class=\"pos\">-aris, <i>m</i></div><div class=\"def\"><num>①</num> ボッカル《 (1) 第2次 Poeni 戦争当時の Mauritania の王.(2) 同じ頃の Numidia 王 Syphax の将軍》.</div><div class=\"def\"><num>②</num> 《詩》アフリカ人.</div>\r\n","<div class=\"hw\">Bocchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ボックス《Mauritania の王;のちに婿の Jugurtha を裏切った》.</div>\r\n","<div class=\"hw\">Bodotria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ボドトリア《Britannia 東岸(現 Scotland)の入江;現 Firth of Forth》.</div>\r\n","<div class=\"hw\">Boebē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボエベー, <SUP>*</SUP>ボイベー《Thessalia の湖》.</div>\r\n","<div class=\"hw\">Boebēis</div><div class=\"pos\">-idos, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sc. </i> lacus)=<a href=\"entry://Boebē\">Boebe</a>.</div>\r\n","<div class=\"hw\">Boebēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thessalia の.</div>\r\n","<div class=\"hw\">Boeōtarchēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Boeotia の最高行政長官.</div>\r\n","<div class=\"hw\">Boeōtia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボエオーティア, <SUP>*</SUP>ボイオーティアー《中部ギリシアの一地域;首都は Thebae》.</div>\r\n","<div class=\"hw\">Boeōticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Boeōtius\">Boeotius</a>.</div>\r\n","<div class=\"hw\">Boeōtius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Boeotia の.</div><div class=\"hw2\"><b>Boeōt(i)ī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Boeotia の住民.</div>\r\n","<div class=\"hw\">Boeōtus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Boeōtius\">Boeotius</a>.</div><hr><div class=\"hw\">Boeōtus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Boeotia 人.</div><div class=\"def\"><num>②</num> 〘伝説〙ボエオートゥス, <SUP>*</SUP>ボイオートス《Neptunus の息子;Boeotia 人の祖》.</div>\r\n","<div class=\"hw\">Bogud</div><div class=\"pos\">-udis, <i>m</i></div><div class=\"def\">ボグド《Bocchus の息子で Mauritania の王;Agrippa にとらえられて殺された》.</div>\r\n","<div class=\"hw\">Boia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Boii 族の国.</div>\r\n","<div class=\"hw\">Boiohaemum, Bohaemum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">(Germania における)Boii 族の国(現 Bohemia).</div>\r\n","<div class=\"hw\">Boius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Boii 族の.</div>\r\n","<div class=\"hw\">Boiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ボイイー《Gallia から北イタリアに移住したケルト系一部族》.</div>\r\n","<div class=\"hw\">bolbiton</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">牛糞.</div>\r\n","<div class=\"hw\">bolbīnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://bulbīnē\">bulbine</a>.</div>\r\n","<div class=\"hw\">bolis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">流星.</div>\r\n","<div class=\"hw\">bolus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (さいころを)投げること.</div><div class=\"def\"><num>②</num> ひと網の漁獲.</div><div class=\"def\"><num>③</num> もうけ, 利益</div><div class=\"ex\"><i>bolo tangere alqm</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ある人をだまして金を巻き上げる.</span></div>\r\n","<div class=\"hw\">bolōnae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\"><num>①</num> 魚卸商.</div><div class=\"def\"><num>②</num> ひと網の漁獲.</div>\r\n","<div class=\"hw\">bombax</div><div class=\"pos\"><i>int</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(驚嘆を表わす)おやまあ.</div>\r\n","<div class=\"hw\">bombicō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">鳴り響く.</div>\r\n","<div class=\"hw\">bombilō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">ブンブンいう.</div>\r\n","<div class=\"hw\">bombizātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">(ハチの)ブンブンいう音.</div>\r\n","<div class=\"hw\">bombiō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブンブンいう.</div>\r\n","<div class=\"hw\">bombus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">低い音;(ハチの)ブンブンいう音.</div>\r\n","<div class=\"hw\">bombylis</div><div class=\"pos\">-is [-idis], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘昆〙カイコのさなぎ.</div>\r\n","<div class=\"hw\">bombyx</div><div class=\"pos\">-ȳcis, <i>m</i>, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘昆〙カイコ(蚕).</div><div class=\"def\"><num>②</num> 絹;絹織物.</div>\r\n","<div class=\"hw\">bombȳcias</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">笛を作るのに適したアシ(葦).</div>\r\n","<div class=\"hw\">bombȳcinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bombyx]</div><div class=\"def\">絹の.</div>\r\n","<div class=\"hw\">Bomilcar</div><div class=\"pos\">-aris, <i>m</i></div><div class=\"def\">ボミルカル《 (1) 第2次 Poeni 戦争中の Carthago の海軍指揮官.(2) Jugurtha の腹心》.</div>\r\n","<div class=\"hw\">Bona Dea</div><div class=\"pos\">-ae -ae, <i>f</i></div><div class=\"def\">〘神話〙ボナ・デア《「良い女神」 の意で, ローマの貞潔と多産の女神;女性に崇拝された》.</div>\r\n","<div class=\"hw\">bonememorius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bonus<SUP>1</SUP>/memoria]</div><div class=\"def\">《碑》よい思い出の.</div>\r\n","<div class=\"hw\">boniloquium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[bonus<SUP>1</SUP>/loquor]</div><div class=\"def\">美辞麗句, お世辞.</div>\r\n","<div class=\"hw\">bonitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[bonus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 高潔, 徳, 誠実.</div><div class=\"def\"><num>②</num> 優良, 優秀.</div><div class=\"def\"><num>③</num> 親切, 善意, 仁愛.</div>\r\n","<div class=\"hw\">Bonna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ボンナ《Rhenus 河畔の町;現 Bonn》.</div>\r\n","<div class=\"hw\">Bonnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Bonna の.</div>\r\n","<div class=\"hw\">bonum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://bonus\">bonus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 善, 徳</div><div class=\"ex\"><i>～ et aequum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">公正.</span></div><div class=\"def\"><num>②</num> 優秀, 長所.</div><div class=\"def\"><num>③</num> (<i>pl</i>)財産, 資産</div><div class=\"ex\"><i>in bonis esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">所有している</span></div><div class=\"ex\"><i>paterna bona</i> (<author>C<small>ATUL</small></author>)<span class=\"ext\">父方の世襲財産</span></div><div class=\"ex\"><i>bona alcis publicare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">ある人の財産を没収する.</span></div><div class=\"def\"><num>④</num> 益, 得</div><div class=\"ex\"><i>alci bono esse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人にとって有利である</span></div><div class=\"ex\"><i>～ publicum</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">公共の福祉.</span></div>\r\n","<div class=\"hw\">bonus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>comp</i> melior, <i>superl</i> optimus)</div><div class=\"def\"><num>①</num> 良い, すぐれた</div><div class=\"ex\"><i>bona tempestas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">上天気</span></div><div class=\"ex\"><i>boni nummi</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">真正の(偽造ではない)貨幣</span></div><div class=\"ex\"><i>bona fides</i> (<author>C<small>IC</small></author>)<span class=\"ext\">善意</span></div><div class=\"ex\"><i>boni mores</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">良俗.</span></div><div class=\"def\"><num>②</num> 有効な;適した 〈re;alci rei;ad alqd〉.</div><div class=\"def\"><num>③</num> 有能な.</div><div class=\"def\"><num>④</num> 望ましい, 満足のいく.</div><div class=\"def\"><num>⑤</num> 強い, 健全な.</div><div class=\"def\"><num>⑥</num> かなりの, たくさんの</div><div class=\"ex\"><i>bona pars sermonis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">談論のかなりの部分.</span></div><div class=\"def\"><num>⑦</num> 有利な, 好都合の.</div><div class=\"def\"><num>⑧</num> 善良な, 高潔な, りっぱな.</div><div class=\"def\"><num>⑨</num> 親切な, 慈悲深い 〈alci;in alqm〉.</div><div class=\"def\"><num>⑩</num> 忠実な.</div><div class=\"def\"><num>⑪</num> 妥当な.</div><hr><div class=\"hw\">bonus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 善良な人.</div><div class=\"def\"><num>②</num> 勇士.</div><div class=\"def\"><num>③</num> 紳士.</div><div class=\"def\"><num>④</num> (<i>pl</i>)上流階級, 保守派.</div>\r\n","<div class=\"hw\">bonuscula</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl dim</i></div><div class=\"ori\">[bonum]</div><div class=\"def\">わずかな財産.</div>\r\n","<div class=\"hw\">bonātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bonus<SUP>1</SUP>]</div><div class=\"def\">気立てのよい.</div>\r\n","<div class=\"hw\">Bonōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ボノーニア《Gallia Cisalpina の町;現 Bologna》.</div>\r\n","<div class=\"hw\">Bonōniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Bononia の.</div>\r\n","<div class=\"hw\">Bora</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ボラ《Macedonia の山》.</div>\r\n","<div class=\"hw\">boragināceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ムラサキ科.</div>\r\n","<div class=\"hw\">borax</div><div class=\"pos\">-acis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘化〙ホウ砂.</div>\r\n","<div class=\"hw\">boreālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://boreās\">boreās</a>]</div><div class=\"def\">北の.</div>\r\n","<div class=\"hw\">boreās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 北風(=<a href=\"entry://aquilō\">aquilo</a>).</div><div class=\"def\"><num>②</num> 北.</div><div class=\"def\"><num>③</num> (B-)〘神話〙ボレアース《ギリシア神話の北風の神;ローマ神話の Aquilo に当たる》.</div>\r\n","<div class=\"hw\">boreōtis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">北の.</div>\r\n","<div class=\"hw\">Borysthenidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Borysthenes 河畔の住民.</div>\r\n","<div class=\"hw\">Borysthenius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Borysthenes 川の</div><div class=\"ex\"><i>～ amnis</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Borysthenēs\">Borysthenes</a>.</span></div>\r\n","<div class=\"hw\">Borysthenēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボリュステネース《黒海に注ぐ Sarmatia の大河;現 Dnepr》.</div>\r\n","<div class=\"hw\">borēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[boreas]</div><div class=\"def\">北の.</div>\r\n","<div class=\"hw\">borīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鉱〙碧玉の一種.</div>\r\n","<div class=\"hw\">borīth</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘植〙シャボンソウ.</div>\r\n","<div class=\"hw\">boscis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙カモの一種.</div>\r\n","<div class=\"hw\">Bosp(h)oricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Bosp(h)orānus\">Bosphoranus</a>.</div>\r\n","<div class=\"hw\">Bosp(h)orius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Bosphorus (1)  (2) の.</div>\r\n","<div class=\"hw\">Bosp(h)orus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボスポルス, <SUP>*</SUP>-ロス, <SUP>∥</SUP>-ラス《 (1) ～ <i>Thracius</i>, Pontus Euxinus と Propontis の間の海峡.(2) ～ <i>Cimmerius</i>, Maeotis palus(現 Azov 海)と Pontus Euxinus の間の海峡》.</div>\r\n","<div class=\"hw\">Bosp(h)orānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bosphorus (2) の.</div>\r\n","<div class=\"hw\">Bostra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ボストラ《Arabia Petraea の町;Trajanus 帝以降, ローマの属州 Arabia の首都;現 Busra》.</div>\r\n","<div class=\"hw\">bostrychus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">巻毛の.</div>\r\n","<div class=\"hw\">Bostrēnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Bostra の住民.</div>\r\n","<div class=\"hw\">botanica</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">植物学.</div>\r\n","<div class=\"hw\">botanicum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">植物標本室.</div>\r\n","<div class=\"hw\">botanicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">植物の[に関する].</div>\r\n","<div class=\"hw\">botanismus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">除草.</div>\r\n","<div class=\"hw\">botanista</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"def\">植物学者.</div>\r\n","<div class=\"hw\">botellus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[botulus]</div><div class=\"def\">小さなソーセージ.</div>\r\n","<div class=\"hw\">botrus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> ブドウの房.</div><div class=\"def\"><num>②</num> 房状の星団.</div>\r\n","<div class=\"hw\">botruōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://botrus\">botrus</a>]</div><div class=\"def\">房状の.</div>\r\n","<div class=\"hw\">botryon<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">薬の一種.</div>\r\n","<div class=\"hw\">botrys</div><div class=\"pos\">-yos, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ヨモギ.</div>\r\n","<div class=\"hw\">botryītis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘鉱〙カラミンの一種.</div><div class=\"def\"><num>②</num> 宝石の一種.</div>\r\n","<div class=\"hw\">botryō(n)<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブドウの房.</div>\r\n","<div class=\"hw\">Bottiaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボッティアエア, <SUP>*</SUP>-アイアー《Macedonia の一地方》.</div>\r\n","<div class=\"hw\">botulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ソーセージ.</div>\r\n","<div class=\"hw\">botulārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://botulus\">botulus</a>]</div><div class=\"def\">ソーセージ屋.</div>\r\n","<div class=\"hw\">Boudicca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ボウディッカ《Britannia の Iceni 族の女王;ローマに対する反乱を指揮した(61年)》.</div>\r\n","<div class=\"hw\">boum</div><div class=\"pos\"><i>pl gen</i></div><div class=\"def\">⇒<a href=\"entry://bōs\">bos</a>.</div>\r\n","<div class=\"hw\">bova</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://boa\">boa</a>.</div>\r\n","<div class=\"hw\">Bovillae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ボウィッラエ《Via Appia 沿いの Latium の町;その近くで Clodius Milo に殺された;⇒ <a href=\"entry://Milō\">Milo</a>》.</div>\r\n","<div class=\"hw\">Bovillensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">《碑》Bovillae の住民.</div>\r\n","<div class=\"hw\">bovillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛の(=<a href=\"entry://būbulus\">bubulus</a>).</div>\r\n","<div class=\"hw\">Bovillānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bovillae の.</div>\r\n","<div class=\"hw\">bovis</div><div class=\"pos\"><i>sg gen</i></div><div class=\"def\">⇒<a href=\"entry://bōs\">bos</a>.</div>\r\n","<div class=\"hw\">Boviānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ボウィアーヌム《Samnium の二つの町》.</div>\r\n","<div class=\"hw\">bovārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://boārius\">boarius</a>.</div>\r\n","<div class=\"hw\">bovātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛のように.</div>\r\n","<div class=\"hw\">bovīle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"def\">=<a href=\"entry://būbīle\">bubile</a>.</div>\r\n","<div class=\"hw\">bovīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://bovillus\">bovillus</a>.</div>\r\n","<div class=\"hw\">bovīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛の.</div>\r\n","<div class=\"hw\">bovō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://boō\">boo</a>.</div>\r\n","<div class=\"hw\">boārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛の</div><div class=\"ex\"><i>forum boarium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ローマ市の牛市場.</span></div>\r\n","<div class=\"hw\">boātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[boo]</div><div class=\"def\">(牛の)鳴き声;大きな叫び声.</div>\r\n","<div class=\"hw\">Boēthius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ボエーティウス《<i>Anicius Manlius Severius ～</i>, ローマの哲学者・政治家(480?‐?524)》.</div>\r\n","<div class=\"hw\">Boēthus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ボエートゥス, <SUP>*</SUP>-トス《 (1) Chalcedon 出身の彫刻家(前2世紀).(2) Sidon 出身のストア学派哲学者(前2世紀)》.</div>\r\n","<div class=\"hw\">boō</div><div class=\"pos\">-āre [-ere], <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> ほえる, うなる;叫ぶ.</div><div class=\"def\"><num>②</num> (場所が)反響する.</div>\r\n","<div class=\"hw\">Boōtēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘天〙牛飼い座.</div>\r\n","<div class=\"hw\">brabeuta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(競技の)審判員.</div>\r\n","<div class=\"hw\">brabēum, -īum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(競技の)勝者への賞品.</div>\r\n","<div class=\"hw\">brachyūra</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘動〙短尾類.</div>\r\n","<div class=\"hw\">bracte-</div><div class=\"def\">⇒bratte-.</div>\r\n","<div class=\"hw\">branchiae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>-chia</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(魚の)えら.</div>\r\n","<div class=\"hw\">branchiata</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘動〙有鰓<SUB>ゆうさい</SUB>類.</div>\r\n","<div class=\"hw\">Branchidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Branchus の子孫《代々神官職を受け継いだ》.</div>\r\n","<div class=\"hw\">Branchidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Apollo の添え名の一つ.</div>\r\n","<div class=\"hw\">branchiūra</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘魚〙鰓尾類.</div>\r\n","<div class=\"hw\">branchos</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">しゃがれ声.</div>\r\n","<div class=\"hw\">Branchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ブランクス, <SUP>*</SUP>-コス《Apollo から予言能力を授けられ, Miletus 南郊 Didyma の Apollo 神託所の神官となった》.</div>\r\n","<div class=\"hw\">brandeum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">聖遺物にかぶせるおおい.</div>\r\n","<div class=\"hw\">Brannoviī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブランノウィイー《Aedui 族に従属したケルト系の一部族》.</div>\r\n","<div class=\"hw\">Brannovīces</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ブランノウィーケス《Gallia Celtica にいた Aulerci 族の一支族》.</div>\r\n","<div class=\"hw\">brasmatiae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">地震.</div>\r\n","<div class=\"hw\">brassica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙キャベツ.</div>\r\n","<div class=\"hw\">brastae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://brasmatiae\">brasmatiae</a>.</div>\r\n","<div class=\"hw\">brathy</div><div class=\"pos\">-ys, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ビャクシン.</div>\r\n","<div class=\"hw\">brattea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">金属の薄片;(特に)金箔.</div>\r\n","<div class=\"hw\">bratteola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[brattea]</div><div class=\"def\">金箔.</div>\r\n","<div class=\"hw\">bratteātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://brattea\">brattea</a>]</div><div class=\"def\"><num>①</num> 金めっきした.</div><div class=\"def\"><num>②</num> 金のように光る.</div><div class=\"def\"><num>③</num> 虚飾の, まやかしの.</div>\r\n","<div class=\"hw\">Bratuspantium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ブラトゥスパンティウム《Gallia Belgica にあった Bellovaci 族の町》 .</div>\r\n","<div class=\"hw\">Brennus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブレンヌス《 (1) Allia 川でローマ軍を破った(前390?)Gallia 人の指導者.(2) ギリシアに侵攻した(前279)Gallia 人の指導者》.</div>\r\n","<div class=\"hw\">brephotrophēum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">孤児院.</div>\r\n","<div class=\"hw\">Breunī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブレウニー《Raetia にいた一部族》.</div>\r\n","<div class=\"hw\">breve</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 短時間</div><div class=\"ex\"><i>ad ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">わずかの間.</span></div><div class=\"def\"><num>②</num> 短い話</div><div class=\"ex\"><i>in brevi</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">手短かに言えば.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 概要.</div>\r\n","<div class=\"hw\">brevia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">浅瀬.</div>\r\n","<div class=\"hw\">breviculus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">(やや)短い, (やや)小さな.</div><hr><div class=\"hw\">breviculus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">小冊子, 摘要.</div>\r\n","<div class=\"hw\">breviloquens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[brevis<SUP>1</SUP>/loquor]</div><div class=\"def\">手短かに話す.</div>\r\n","<div class=\"hw\">breviloquentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://breviloquens\">breviloquens</a>]</div><div class=\"def\">表現の簡潔さ.</div>\r\n","<div class=\"hw\">brevis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 短い, 小さい, 狭い.</div><div class=\"def\"><num>②</num> 浅い;低い.</div><div class=\"def\"><num>③</num> 少ない, わずかな.</div><div class=\"def\"><num>④</num> (時間が)短い;短時間の, 束<SUB>つか</SUB>の間の</div><div class=\"ex\"><i>ira furor ～ est</i> (<author>H<small>OR</small></author>)<span class=\"ext\">怒りは一時の狂気だ.</span></div><div class=\"def\"><num>⑤</num> 簡潔な.</div><div class=\"def\"><num>⑥</num> (音節が)短い.</div><hr><div class=\"hw\">brevis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">(<i>sc. </i> syllaba)〘文〙短音節.</div><hr><div class=\"hw\">brevis<SUP>3</SUP></div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(<i>sc. </i> liber, libellus)概要;目録.</div>\r\n","<div class=\"hw\">breviter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">短く;簡潔に.</div>\r\n","<div class=\"hw\">brevitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 短さ, 狭さ.</div><div class=\"def\"><num>②</num> (時間の)短さ.</div><div class=\"def\"><num>③</num> (表現の)簡潔さ.</div><div class=\"def\"><num>④</num> (音節が)短いこと.</div>\r\n","<div class=\"hw\">breviārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://breviārius\">breviārius</a>]</div><div class=\"def\"><num>①</num> 概要, 要約</div><div class=\"ex\"><i>～ imperii</i> (<author>S<small>UET</small></author>)<span class=\"ext\">帝国の現状要覧.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘カト〙聖務日課書.</div>\r\n","<div class=\"hw\">breviārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">要約した.</div>\r\n","<div class=\"hw\">breviātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">要約して, 簡略に.</div>\r\n","<div class=\"hw\">breviātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\">短縮;要約.</div>\r\n","<div class=\"hw\">breviō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://brevis\">brevis<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 短くする, 短縮する.</div><div class=\"def\"><num>②</num> (音節を)短く発音する.</div>\r\n","<div class=\"hw\">brevī</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 短時間に</div><div class=\"ex\"><i>～ post</i> (<author>L<small>IV</small></author>)<span class=\"ext\">直後に</span></div><div class=\"ex\"><i>～ ante</i> (<author>S<small>EN</small> M<small>AJ</small></author>)<span class=\"ext\">直前に.</span></div><div class=\"def\"><num>②</num> 簡潔に, 手短かに.</div>\r\n","<div class=\"hw\">Briareus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ブリアレウス(=<a href=\"entry://Aegaeōn\">Aegaeon</a>).</div>\r\n","<div class=\"hw\">bridus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">炊事道具の一種《おそらく肉をあぶる焼き串回転具》.</div>\r\n","<div class=\"hw\">Brigantes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ブリガンテス《Britannia 北部にいたケルト系一部族;Agricola 達に征服された(71‐79)》.</div>\r\n","<div class=\"hw\">Brigantia<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《碑》ブリガンティア《Brigantes 族の女神》.</div><hr><div class=\"hw\">Brigantia<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ブリガンティア《Raetia の町;現 Bregenz》.</div>\r\n","<div class=\"hw\">Brigantium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">ブリガンティウム《 (1) Gallia Narbonensis の町;現 Briançon.(2) Gallaecia の町;現 Coruña》.</div>\r\n","<div class=\"hw\">Brigantīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Brigantia<SUP>2</SUP> の</div><div class=\"ex\"><i>～ lacus</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">現 Bodensee.</span></div>\r\n","<div class=\"hw\">Briniātes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">ブリニアーテス《Liguria 東部の一部族》.</div>\r\n","<div class=\"hw\">Britannia, Brittannia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブリタンニア, <SUP>∥</SUP>ブリタニア《広義には Albion, Hibernia を含むが, 狭義には Albion のみ》.</div>\r\n","<div class=\"hw\">Britanniciānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》Britannia の.</div>\r\n","<div class=\"hw\">Britannicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Britannia の.</div><hr><div class=\"hw\">Britannicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブリタンニクス《Claudius 帝の息子の添え名;父の Britannia 侵攻の成功にちなんで名づけられた;のちに義母 Agrippina とその連れ子で皇帝となった Nero に毒殺された》.</div>\r\n","<div class=\"hw\">Britannis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>adj f</i></div><div class=\"def\">Britannia の.</div>\r\n","<div class=\"hw\">Britannus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Britannicus\">Britannicus<SUP>1</SUP></a>.</div><hr><div class=\"hw\">Britannus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(集合的に)Britannia 人.</div>\r\n","<div class=\"hw\">Britomartis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ブリトマルティス《Juppiter の娘で Creta 島のニンフ;のちに Diana と同一視された》.</div>\r\n","<div class=\"hw\">Brittiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Bruttiī\">Bruttii</a>.</div>\r\n","<div class=\"hw\">Britto</div><div class=\"pos\">-<img class=\"font\" src=\"img/A13A.png\">nis, <i>m</i></div><div class=\"def\">Britannia の住民.</div>\r\n","<div class=\"hw\">Brixellum, Brixillum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ブリクセッルム《Gallia Cisalpina の町;現 Brescello》.</div>\r\n","<div class=\"hw\">Brixia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブリクシア《Gallia Cisalpina の町;現 Brescia》.</div>\r\n","<div class=\"hw\">Brixiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Brixia の.</div>\r\n","<div class=\"hw\">brocchitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://brocc(h)us\">brocc(h)us</a>]</div><div class=\"def\">(動物の)歯が突き出ていること.</div>\r\n","<div class=\"hw\">brocc(h)us</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">出っ歯の.</div>\r\n","<div class=\"hw\">brochon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://bdellium\">bdellium 2</a>.</div>\r\n","<div class=\"hw\">Brogitarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブロギタルス《Deiotarus 王の婿》.</div>\r\n","<div class=\"hw\">bromeliāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙パイナップル科.</div>\r\n","<div class=\"hw\">Bromius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(「騒々しい者」 の意)Bacchus の呼称の一つ.</div>\r\n","<div class=\"hw\">bromos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙カラスムギ.</div>\r\n","<div class=\"hw\">bronchia</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙気管支.</div>\r\n","<div class=\"hw\">bronchiolī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl dim</i></div><div class=\"ori\">[bronchus]</div><div class=\"def\">〘解〙細気管支.</div>\r\n","<div class=\"hw\">bronchiālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙気管支の.</div>\r\n","<div class=\"hw\">bronchus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙気管支.</div>\r\n","<div class=\"hw\">bronchītis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://bronchus\">bronchus</a>]</div><div class=\"def\">〘病〙気管支炎.</div>\r\n","<div class=\"hw\">brontea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> Bronte]</div><div class=\"def\">雷石.</div>\r\n","<div class=\"hw\">Brontē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">雷神.</div>\r\n","<div class=\"hw\">Brontēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ブロンテース《Cyclopes の一人》.</div>\r\n","<div class=\"hw\">Brontōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》(「雷をとどろかせる者」 の意)Juppiter の呼称の一つ.</div>\r\n","<div class=\"hw\">Bructerus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bructeri 族の.</div>\r\n","<div class=\"hw\">Bructerī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブルクテリー《Germania 北西部にいたゲルマン系一部族》.</div>\r\n","<div class=\"hw\">Bruges, Brugius</div><div class=\"def\">⇒<a href=\"entry://Phryges\">Phryges</a>, <a href=\"entry://Phrygius\">Phrygius</a>.</div>\r\n","<div class=\"hw\">Brundisium, Brundusium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ブルンディシウム《アドリア海に臨む Calabria の港町;重要な海軍基地;現 Brindisi》.</div>\r\n","<div class=\"hw\">Brundisīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Brundisium の.</div><div class=\"hw2\"><b>Brundisīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Brundisium の住民.</div>\r\n","<div class=\"hw\">bruscum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">カエデの木にできたこぶ.</div>\r\n","<div class=\"hw\">Bruttax</div><div class=\"pos\">-ācis, <i>m</i></div><div class=\"def\">Bruttii 人.</div>\r\n","<div class=\"hw\">Bruttius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bruttii の.</div>\r\n","<div class=\"hw\">Bruttiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブルッティイー《 (1) イタリア半島の南端地方.(2) その住民》.</div>\r\n","<div class=\"hw\">brya</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ギョリュウ属の低木(=<a href=\"entry://myrīca\">myrica</a>).</div>\r\n","<div class=\"hw\">bryon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> ミズゴケの一種(=<a href=\"entry://sphagnos\">sphagnos</a>).</div><div class=\"def\"><num>②</num> ハクヨウの尾状花序.</div><div class=\"def\"><num>③</num> 海草の一種.</div>\r\n","<div class=\"hw\">bryophyta</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘植〙蘚苔<SUB>せんたい</SUB>類.</div>\r\n","<div class=\"hw\">bryopsidāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙(クダモ目)ハネモ科.</div>\r\n","<div class=\"hw\">bryōnia</div><div class=\"pos\">-ae, <B>bryōnias</B> -adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ブリオニア.</div>\r\n","<div class=\"hw\">brācae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>brāca</B> -ae, <i>f</i></div><div class=\"def\">(ゆったりした)ズボン.</div>\r\n","<div class=\"hw\">Brācarus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》Bracari 族の.</div>\r\n","<div class=\"hw\">Brācarī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブラーカリー《Hispania Tarraconensis にいた一部族》.</div>\r\n","<div class=\"hw\">brāchiolum, bracch-</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[brachium]</div><div class=\"def\">(小さい[細い])腕.</div>\r\n","<div class=\"hw\">brāchiopoda</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘動〙腕足動物門.</div>\r\n","<div class=\"hw\">brāchium, bracch-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 腕;(特に)前腕.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙上腕.</div><div class=\"def\"><num>③</num> (動物の)前足;(カニなどの)はさみ.</div><div class=\"def\"><num>④</num> 入江.</div><div class=\"def\"><num>⑤</num> (山の)支脈.</div><div class=\"def\"><num>⑥</num> 木の枝.</div><div class=\"def\"><num>⑦</num> 《詩》帆桁;(投石機の)腕木.</div><div class=\"def\"><num>⑧</num> (港の)突堤.</div><div class=\"def\"><num>⑨</num> (コンパスの)脚.</div><div class=\"def\"><num>⑩</num> 〘軍〙外堡<SUB>がいほう</SUB>, 外塁.</div>\r\n","<div class=\"hw\">brāchiāle, bracch-</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://brāchiālis\">brāchiālis<SUP>1</SUP>, bracch-<SUP>1</SUP></a>]</div><div class=\"def\">腕輪, ブレスレット.</div>\r\n","<div class=\"hw\">brāchiālis<SUP>1</SUP>, bracch-<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[brachium]</div><div class=\"def\"><num>①</num> 腕の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙上腕の.</div><hr><div class=\"hw\">brāchiālis<SUP>2</SUP>, bracch-<SUP>2</SUP></div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://brāchiāle\">brachiale</a>.</div>\r\n","<div class=\"hw\">brāchiātus, bracch-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[brachium]</div><div class=\"def\"><num>①</num> 枝を張った.</div><div class=\"def\"><num>②</num> 《碑》(兵士が)腕甲をつけた.</div>\r\n","<div class=\"hw\">brācātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bracae]</div><div class=\"def\"><num>①</num> ズボンをはいた.</div><div class=\"def\"><num>②</num> 異国の, 野蛮な.</div><div class=\"def\"><num>③</num> <i>Gallia Bracata</i> (<author>P<small>LIN</small></author>) のちの Gallia Narbonensis.</div><div class=\"hw2\"><b>Brācātī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Gallia Bracata の住民.</div>\r\n","<div class=\"hw\">brādō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ハム.</div>\r\n","<div class=\"hw\">Brīmō</div><div class=\"pos\">-ūs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(「怒れる女」 の意)Proserpina(あるいは Hecate)の呼称の一つ.</div>\r\n","<div class=\"hw\">brīsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブドウのしぼりかす.</div>\r\n","<div class=\"hw\">Brīsaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Bacchus の呼称の一つ.</div>\r\n","<div class=\"hw\">Brīsēis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ブリーセーイス《「Brises の娘」 の意;Achilles の奴隷で妾であったが Agamemnon に奪われ, これがこの二大勇士の不和のもとになった》.</div>\r\n","<div class=\"hw\">brōmum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://brōmus\">brōmus</a>]</div><div class=\"def\">〘化〙臭素.</div>\r\n","<div class=\"hw\">brōmus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">悪臭.</div>\r\n","<div class=\"hw\">brōmōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">臭気, 悪臭.</div>\r\n","<div class=\"hw\">brōmōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">臭気を放つ.</div>\r\n","<div class=\"hw\">brūchus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘昆〙バッタの一種.</div>\r\n","<div class=\"hw\">brūma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[brevis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 冬至.</div><div class=\"def\"><num>②</num> 冬, 冬季;冬の寒さ.</div><div class=\"def\"><num>③</num> 年.</div>\r\n","<div class=\"hw\">brūmālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://brūma\">brūma</a>]</div><div class=\"def\"><num>①</num> 冬至の.</div><div class=\"def\"><num>②</num> 冬の.</div>\r\n","<div class=\"hw\">brūmōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bruma]</div><div class=\"def\">冬の.</div>\r\n","<div class=\"hw\">brūtes</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">《碑》新婦, 花嫁.</div>\r\n","<div class=\"hw\">brūtescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[brutus]</div><div class=\"def\">(理性を欠いた)獣のようになる;無感覚になる.</div>\r\n","<div class=\"hw\">Brūtiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Brutus の.</div><div class=\"hw2\"><b>Brūtiānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Brutus (2) 一派の者ども.</div>\r\n","<div class=\"hw\">brūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 重い.</div><div class=\"def\"><num>②</num> 無分別な, 愚鈍な.</div><div class=\"def\"><num>③</num> 理性を欠いた</div><div class=\"ex\"><i>bruta animalia</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">野獣.</span></div>\r\n","<div class=\"hw\">Brūtus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブルートゥス《Junia 氏族に属するローマ人の家名;特に (1) <i>L. Junius ～</i>, 王政を廃してローマ共和政治を創始したといわれる(前500年頃).(2) <i>M. Junius ～</i>, Caesar 暗殺の首謀者(前85?‐42).(3) <i>D. Junius ～</i>, 政治家・軍人;Caesar の武将でその暗殺者の一人(前84‐43)》.</div>\r\n","<div class=\"hw\">brūtālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://brūtālis\">brūtālis</a>]</div><div class=\"def\">理性のない動物, 獣.</div>\r\n","<div class=\"hw\">brūtālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[brutus]</div><div class=\"def\">獣の, 獣的な;理性のない.</div>\r\n","<div class=\"hw\">Brūtīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Brutus (1) 的な[にふさわしい].</div>\r\n","<div class=\"hw\">Bublos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">=<a href=\"entry://Byblos\">Byblos</a>.</div>\r\n","<div class=\"hw\">bubulcitor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://bubulcitō\">bubulcito</a>.</div>\r\n","<div class=\"hw\">bubulcitō</div><div class=\"pos\">-āre -āvī, <i>intr</i></div><div class=\"ori\">[bubulcus]</div><div class=\"def\"><num>①</num> 牛を飼う[駆る].</div><div class=\"def\"><num>②</num> 牛飼いのように叫ぶ.</div>\r\n","<div class=\"hw\">bubulcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bos, bubulus]</div><div class=\"def\">牛飼い;(牛を使って耕作する)農夫.</div>\r\n","<div class=\"hw\">bucca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 頬<SUB>ほお</SUB></div><div class=\"ex\"><i>buccas inflare</i> (<author>H<small>OR</small></author>)<span class=\"ext\">(怒りで)頬をふくらます.</span></div><div class=\"def\"><num>②</num> 口</div><div class=\"ex\"><i>quod in buccam venerit scribito</i> (<author>C<small>IC</small></author>)<span class=\"ext\">何でも思いついたことを(手紙に)書いて下さい.</span></div><div class=\"def\"><num>③</num> がなり立てる人.</div><div class=\"def\"><num>④</num> (食物の)一口分.</div><div class=\"def\"><num>⑤</num> 〘解〙(膝関節の)窩<SUB>か</SUB>.</div>\r\n","<div class=\"hw\">buccella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://bucca\">bucca</a>]</div><div class=\"def\"><num>①</num> (食物の)ほんの一口分.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(貧者に支給される)小さなパン.</div>\r\n","<div class=\"hw\">buccin-</div><div class=\"def\">⇒bucin-.</div>\r\n","<div class=\"hw\">buccinātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘解〙頬筋<SUB>きょうきん</SUB>.</div>\r\n","<div class=\"hw\">buccopharyngeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙頬咽頭の.</div>\r\n","<div class=\"hw\">buccula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[bucca]</div><div class=\"def\"><num>①</num> (小さな)頬<SUB>ほお</SUB>.</div><div class=\"def\"><num>②</num> (かぶとの)面頬<SUB>めんぽお</SUB>.</div>\r\n","<div class=\"hw\">bucculentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://buccula\">buccula</a>]</div><div class=\"def\">頬<SUB>ほお</SUB>のふくらんだ.</div>\r\n","<div class=\"hw\">buccō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[bucca]</div><div class=\"def\">おしゃべりなばか者.</div>\r\n","<div class=\"hw\">buccōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bucca]</div><div class=\"def\">大きな口の.</div>\r\n","<div class=\"hw\">buda</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙スゲ(=<a href=\"entry://ulva\">ulva</a>).</div>\r\n","<div class=\"hw\">Budalia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">ブダリア《Pannonia Inferior(南部)の町》.</div>\r\n","<div class=\"hw\">bugillō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘植〙ヨウシュジュウニヒトエ.</div>\r\n","<div class=\"hw\">bulbocavernōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙球海綿体の.</div>\r\n","<div class=\"hw\">bulboīdeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙球状の.</div>\r\n","<div class=\"hw\">bulboūrethrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解・動〙尿道球の.</div>\r\n","<div class=\"hw\">bulbus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 球根;〘植〙鱗茎.</div><div class=\"def\"><num>②</num> タマネギ.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙球</div><div class=\"ex\"><i>～ oculi</i><span class=\"ext\">眼球.</span></div>\r\n","<div class=\"hw\">bulbāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bulbus]</div><div class=\"def\">球根のある.</div>\r\n","<div class=\"hw\">bulbīnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">球根植物の一種.</div>\r\n","<div class=\"hw\">bulbōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bulbus]</div><div class=\"def\">球根のある.</div>\r\n","<div class=\"hw\">bulga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 皮袋, 背嚢.</div><div class=\"def\"><num>②</num> 子宮.</div>\r\n","<div class=\"hw\">bulla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 泡, 水泡.</div><div class=\"def\"><num>②</num> (帯の)飾り金;(扉の)飾り鋲.</div><div class=\"def\"><num>③</num> (子供が身につけた魔よけ入りの)首飾り.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘カト〙ローマ教皇印;(教皇の)大勅書.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘病〙水疱.</div>\r\n","<div class=\"hw\">bullescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[bulla]</div><div class=\"def\">泡立つ.</div>\r\n","<div class=\"hw\">Bulli(d)ensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Bullis の住民.</div>\r\n","<div class=\"hw\">Bullis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブッリス, <SUP>*</SUP>ブーリッス《Illyria の町》.</div>\r\n","<div class=\"hw\">bulliō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i>, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[bulla]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 泡立つ, 沸騰する.</div><div class=\"def\"><num>②</num> 激昂する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)沸騰させる.</div>\r\n","<div class=\"hw\">bullula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[bulla]</div><div class=\"def\"><num>①</num> (小さな)水泡.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(小さな)首飾り.</div>\r\n","<div class=\"hw\">bullārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://bulla\">bulla</a>]</div><div class=\"def\">〘カト〙大勅書集.</div>\r\n","<div class=\"hw\">bullātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bulla]</div><div class=\"def\"><num>①</num> 飾り金のついた.</div><div class=\"def\"><num>②</num> 魔よけ入りの首飾りを身につけた;子供の.</div>\r\n","<div class=\"hw\">Bullīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Bulli(d)ensēs\">Bullidenses</a>.</div>\r\n","<div class=\"hw\">bullītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[bullio]</div><div class=\"def\">(水の)泡.</div>\r\n","<div class=\"hw\">bullō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[bulla]</div><div class=\"def\">泡立つ, 沸騰する.</div>\r\n","<div class=\"hw\">Burdigala</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブルディガラ《Aquitania の Garumna(現 Garonne)河畔の町;Bituriges Vivisci 族の首都;現 Bordeaux》.</div>\r\n","<div class=\"hw\">burdunculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[burdo]</div><div class=\"def\">〘植〙ルリヂサ.</div>\r\n","<div class=\"hw\">burdō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘動〙ラバ《雌馬と雄ロバの雑種》.</div>\r\n","<div class=\"hw\">burdōnārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://burdō\">burdō</a>]</div><div class=\"def\">ラバ引き.</div>\r\n","<div class=\"hw\">burgus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\"><num>①</num> 城塞.</div><div class=\"def\"><num>②</num> 町.</div>\r\n","<div class=\"hw\">burgāriī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">城塞に住む者たち;町の住人.</div>\r\n","<div class=\"hw\">burmanniāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ヒナノシャクジョウ科.</div>\r\n","<div class=\"hw\">burra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[burrus]</div><div class=\"def\"><num>①</num> 羊毛の粗末な生地.</div><div class=\"def\"><num>②</num> (<i>pl</i>)たわごと.</div>\r\n","<div class=\"hw\">burric(h)us</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://burrus\">burrus</a>]</div><div class=\"def\">小形の馬.</div>\r\n","<div class=\"hw\">burrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">緋色の, 赤い.</div>\r\n","<div class=\"hw\">Burrus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《古形》=<a href=\"entry://Pyrrhus\">Pyrrhus</a>.</div><hr><div class=\"hw\">Burrus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ブッルス《ローマ人の家名;特に <i>Sex. Afranius ～</i>, Nero 帝の教師》.</div>\r\n","<div class=\"hw\">burrānicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[burrus]</div><div class=\"def\"><i>burranica potio</i> (<author>F<small>EST</small></author>) ミルクとブドウ液を混ぜた飲料.</div>\r\n","<div class=\"hw\">bursa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 皮革, 皮.</div><div class=\"def\"><num>②</num> 物入れ, 小袋;〘カト〙ブルサ, 聖布嚢.</div><div class=\"def\"><num>③</num> 〘解〙包, 嚢</div><div class=\"ex\"><i>～ mucosa</i><span class=\"ext\">粘液嚢.</span></div>\r\n","<div class=\"hw\">Bursa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Byrsa\">Byrsa</a>.</div>\r\n","<div class=\"hw\">bustar</div><div class=\"pos\">-aris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[bustum]</div><div class=\"def\">火葬場.</div>\r\n","<div class=\"hw\">busticētum</div><div class=\"pos\">-i, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[bustum]</div><div class=\"def\">火葬場;墓.</div>\r\n","<div class=\"hw\">bustirapus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://bustum\">bustum</a>/rapio]</div><div class=\"def\">墓荒らし.</div>\r\n","<div class=\"hw\">bustiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[bustum]</div><div class=\"def\">焼くこと.</div>\r\n","<div class=\"hw\">bustum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[uro]</div><div class=\"def\"><num>①</num> 火葬用の薪<SUB>まき</SUB>の山.</div><div class=\"def\"><num>②</num> 墓, 塚</div><div class=\"ex\"><i>tu ～ rei publicae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">国家の墓であるあなた.</span></div><div class=\"def\"><num>③</num> (死体を焼いたあとの)灰.</div><div class=\"def\"><num>④</num> 死体.</div><div class=\"def\"><num>⑤</num> (都市の)廃墟.</div>\r\n","<div class=\"hw\">butomāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ハナイ科.</div>\r\n","<div class=\"hw\">buttutī</div><div class=\"pos\"><i>int</i></div><div class=\"def\">Hernici 族が宗教儀式であげた叫び声.</div>\r\n","<div class=\"hw\">butubatta</div><div class=\"pos\"><i>int</i></div><div class=\"def\">つまらない!, くだらない!</div>\r\n","<div class=\"hw\">Butuntī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブトゥンティー《Apulia の町》.</div>\r\n","<div class=\"hw\">buxa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[buxus]</div><div class=\"def\">ツゲ製の容器.</div>\r\n","<div class=\"hw\">buxans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"ori\">[buxus]</div><div class=\"def\">ツゲの色をした.</div>\r\n","<div class=\"hw\">Buxentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ブクセントゥム《Lucania の町;現 Policastro》.</div>\r\n","<div class=\"hw\">buxeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[buxus]</div><div class=\"def\"><num>①</num> ツゲの.</div><div class=\"def\"><num>②</num> ツゲの色をした, 黄ばんだ.</div>\r\n","<div class=\"hw\">buxifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[buxus/fero]</div><div class=\"def\">ツゲの木を産出する.</div>\r\n","<div class=\"hw\">buxineae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ツゲ亜目.</div>\r\n","<div class=\"hw\">buxiārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[buxus]</div><div class=\"def\">《碑》ツゲの木の.</div>\r\n","<div class=\"hw\">buxus</div><div class=\"pos\">-ī, <i>f</i>, <B>buxum</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙ツゲ.</div><div class=\"def\"><num>②</num> ツゲ材.</div><div class=\"def\"><num>③</num> ツゲ製品《笛, こま, 櫛など》.</div>\r\n","<div class=\"hw\">buxāceae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙ツゲ科.</div>\r\n","<div class=\"hw\">buxētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[buxus]</div><div class=\"def\">ツゲの植林地.</div>\r\n","<div class=\"hw\">buxōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://buxus\">buxus</a>]</div><div class=\"def\">ツゲに似た.</div>\r\n","<div class=\"hw\">Byblis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ビュブリス《Miletus の娘;兄 Caunus に恋して拒まれ, 泉に変身させられた》.</div>\r\n","<div class=\"hw\">Byblos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビュブロス《Phoenicia の港町》.</div>\r\n","<div class=\"hw\">Byllis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">=<a href=\"entry://Bullis\">Bullis</a>.</div>\r\n","<div class=\"hw\">byrr(h)us</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://birrus\">birrus</a>.</div>\r\n","<div class=\"hw\">byrsa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://bursa\">bursa</a>.</div>\r\n","<div class=\"hw\">Byrsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビュルサ《Carthago の城塞》.</div>\r\n","<div class=\"hw\">byssinum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://byssinus\">byssinus</a>]</div><div class=\"def\">(上質の)亜麻織物.</div>\r\n","<div class=\"hw\">byssinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">上質の亜麻で織った.</div>\r\n","<div class=\"hw\">byssus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">上質の亜麻.</div>\r\n","<div class=\"hw\">Byzantiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Byzantius\">Byzantius</a>.</div>\r\n","<div class=\"hw\">Byzantium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビュザンティウム, <SUP>*</SUP>-オン, <SUP>∥</SUP>ビザンティウム《Thracia の Bosphorus 海峡左岸のギリシア植民市;330年 Constantinus 大帝がこの地をローマ帝国の首都とさだめて Constantinopolis と呼んだ;のち東ローマ帝国の首都(395‐1453);現 Istanbul》.</div>\r\n","<div class=\"hw\">Byzantius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Byzantium の.</div><div class=\"hw2\"><b>Byzantiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Byzantium の住民.</div>\r\n","<div class=\"hw\">Byzantīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://Byzantius\">Byzantius</a>.</div>\r\n","<div class=\"hw\">bāca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙漿果, ベリー.</div><div class=\"def\"><num>②</num> オリーブの実.</div><div class=\"def\"><num>③</num> 木の実.</div><div class=\"def\"><num>④</num> ベリーに似た形状のもの《真珠など》.</div>\r\n","<div class=\"hw\">bācifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[baca/fero]</div><div class=\"def\"><num>①</num> 漿果を結ぶ.</div><div class=\"def\"><num>②</num> オリーブを実らせる.</div>\r\n","<div class=\"hw\">bācālia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://bāca\">bāca</a>]</div><div class=\"def\">〘植〙ゲッケイジュの一種.</div>\r\n","<div class=\"hw\">bācātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[baca]</div><div class=\"def\">真珠をちりばめた.</div>\r\n","<div class=\"hw\">Bāiae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\"><num>①</num> バイヤエ《Campania の海岸の小さな町;温泉で有名》.</div><div class=\"def\"><num>②</num> (一般に)温泉地.</div>\r\n","<div class=\"hw\">Bāiānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">Baiae 周辺の地域.</div>\r\n","<div class=\"hw\">Bāiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Baiae の.</div>\r\n","<div class=\"hw\">bājulus, bājolus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">荷物運搬人.</div>\r\n","<div class=\"hw\">bājulō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://bājulus\">bājulus, bājolus</a>]</div><div class=\"def\">(荷を)運ぶ, かつぐ.</div>\r\n","<div class=\"hw\">bālaena</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙クジラ.</div>\r\n","<div class=\"hw\">bālantēs</div><div class=\"pos\">-um, <i>f pl</i>(<i>prp</i>)</div><div class=\"ori\">[balo]</div><div class=\"def\">ヒツジ.</div>\r\n","<div class=\"hw\">bālista</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://ballista\">ballista</a>.</div>\r\n","<div class=\"hw\">bālātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[balo]</div><div class=\"def\">(ヤギ・ヒツジなどの)鳴き声.</div>\r\n","<div class=\"hw\">bālō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\">(羊が)鳴く.</div>\r\n","<div class=\"hw\">bāris</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(Nilus 川の)小舟, 平底船.</div>\r\n","<div class=\"hw\">Bārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バーリウム, <SUP>*</SUP>-オン《アドリア海に面する Apulia の港町;現 Bari》.</div>\r\n","<div class=\"hw\">bārītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">=<a href=\"entry://barrītus\">barritus</a>.</div>\r\n","<div class=\"hw\">bārō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ばか者, のろま.</div>\r\n","<div class=\"hw\">bāsiolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[basium]</div><div class=\"def\">軽いキス.</div>\r\n","<div class=\"hw\">bāsium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">接吻, キス.</div>\r\n","<div class=\"hw\">bāsiātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[basio]</div><div class=\"def\">接吻, キス.</div>\r\n","<div class=\"hw\">bāsiātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[basio]</div><div class=\"def\">キスする人.</div>\r\n","<div class=\"hw\">bāsiō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[basium]</div><div class=\"def\">キスする.</div>\r\n","<div class=\"hw\">bātuō</div><div class=\"pos\">-ere, <i>tr</i>, <i>intr</i></div><div class=\"def\">=<a href=\"entry://battuō\">battuo</a>.</div>\r\n","<div class=\"hw\">Bāāl</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">バアル《Syria で崇拝された神》.</div>\r\n","<div class=\"hw\">bēchicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">せき止めの(=<a href=\"entry://tussiculāris\">tussicularis</a>).</div>\r\n","<div class=\"hw\">bēchion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙フキタンポポ.</div>\r\n","<div class=\"hw\">Bēdriacensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Bedriacum の.</div>\r\n","<div class=\"hw\">Bēdriacum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ベードリアクム《イタリア北部のMantua と Cremona の間にあった村》.</div>\r\n","<div class=\"hw\">Bēlis</div><div class=\"pos\">-idos, <i>f</i></div><div class=\"def\">Belus の女系子孫《特に(<i>pl</i> Belides で)孫娘たち Danaides》.</div>\r\n","<div class=\"hw\">bēlua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 獣.</div><div class=\"def\"><num>②</num> 怪物, 怪獣.</div><div class=\"def\"><num>③</num> (軽蔑的に)人でなし, 畜生.</div>\r\n","<div class=\"hw\">Bēlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ベールス, <SUP>*</SUP>-ロス《 (1) Babylon の建設者.(2) Tyrus の王;Dido の父.(3) エジプトの王;Danaus と Aegyptus の父》.</div>\r\n","<div class=\"hw\">bēluālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://bēlua\">bēlua</a>]</div><div class=\"def\">獣の.</div>\r\n","<div class=\"hw\">bēluātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[belua]</div><div class=\"def\">獣の姿を刺繍した.</div>\r\n","<div class=\"hw\">bēluīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[belua]</div><div class=\"def\">獣の(ような).</div>\r\n","<div class=\"hw\">bēluōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[belua]</div><div class=\"def\">獣[怪物]の多い.</div>\r\n","<div class=\"hw\">Bēlīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Belus の子孫《息子 Danaus と Aegyptus;または孫 Lynceus》.</div>\r\n","<div class=\"hw\">bēlūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[belua]</div><div class=\"def\">獣のような.</div>\r\n","<div class=\"hw\">Bēnācus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ベーナークス《イタリア北部の湖;現 Lago di Garda》.</div>\r\n","<div class=\"hw\">bēryllus, -os, bērullus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鉱〙緑柱石.</div>\r\n","<div class=\"hw\">Bērȳtus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベーリュートゥス, <SUP>*</SUP>-トス《Phoenicia の港町;現 Beirut;ローマの植民地としては Felix Julia と呼ばれた》.</div>\r\n","<div class=\"hw\">Bērōnes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ベーローネス《Hispania Tarraconensis にいたケルト系一部族》.</div>\r\n","<div class=\"hw\">bēs</div><div class=\"pos\">bessis, <i>m</i></div><div class=\"def\">3分の2</div><div class=\"ex\"><i>～ alter</i> (<author>V<small>ITR</small></author>)<span class=\"ext\">1<img class=\"font\" src=\"img/B156.png\"></span></div><div class=\"ex\"><i>faenus bessibus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">月利 <img class=\"font\" src=\"img/B156.png\">%(=年利8%).</span></div>\r\n","<div class=\"hw\">bēta<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙ビート.</div><hr><div class=\"hw\">bēta<SUP>2</SUP></div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> ギリシア語アルファベットの第2字(▷Β, β◁).</div><div class=\"def\"><num>②</num> 2番目の物.</div>\r\n","<div class=\"hw\">bētizō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[beta<SUP>1</SUP>]</div><div class=\"def\">気力がない.</div>\r\n","<div class=\"hw\">Bētriac-</div><div class=\"def\">⇒Bedriac-.</div>\r\n","<div class=\"hw\">bētāceus</div><div class=\"def\">-ī, <i>m</i></div><div class=\"ori\">[beta<SUP>1</SUP>]</div><div class=\"def\">ビートの根.</div>\r\n","<div class=\"hw\">bētō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">=<a href=\"entry://bītō\">bito</a>.</div>\r\n","<div class=\"hw\">bīduum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bi-/dies]</div><div class=\"def\">2日(間)</div><div class=\"ex\"><i>biduo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">2日以内に;2日かかって.</span></div>\r\n","<div class=\"hw\">bīduānus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://bīduum\">bīduum</a>]</div><div class=\"def\">2日間の.</div>\r\n","<div class=\"hw\">bīgae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>bīga</B> -ae, <i>f</i></div><div class=\"ori\">[bi-/jugum]</div><div class=\"def\">一対の馬;二頭立て戦車[馬車].</div>\r\n","<div class=\"hw\">bīgātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bigae]</div><div class=\"def\">(硬貨が)2頭立て戦車の刻印のある.</div><hr><div class=\"hw\">bīgātus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> nummus)(2頭立て戦車の刻印のある)ローマの銀貨.</div>\r\n","<div class=\"hw\">bīlis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 胆汁</div><div class=\"ex\"><i>～ suffusa</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">〘病〙黄疸<SUB>おうだん</SUB>.</span></div><div class=\"def\"><num>②</num> 怒り, 不機嫌.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>atra [nigra]</i> ～ (<author>C<small>IC</small> [S<small>EN</small>]</author>)<span class=\"ext\">憂鬱.</span></div>\r\n","<div class=\"hw\">bīliōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://bīlis\">bīlis</a>]</div><div class=\"def\">胆汁の多い.</div>\r\n","<div class=\"hw\">bīmulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://bīmus\">bīmus</a>]</div><div class=\"def\">やっと2歳の.</div>\r\n","<div class=\"hw\">bīmus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bi-/hiems]</div><div class=\"def\"><num>①</num> 2歳の.</div><div class=\"def\"><num>②</num> 2年間の.</div>\r\n","<div class=\"hw\">bīmātus<SUP>1</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[bimus]</div><div class=\"def\">(動植物の)2歳, 2年.</div><hr><div class=\"hw\">bīmātus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">2歳の.</div>\r\n","<div class=\"hw\">bīnārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[bini]</div><div class=\"def\">二つの, 二重の.</div>\r\n","<div class=\"hw\">bīnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[bis]</div><div class=\"def\"><num>①</num> 二つずつの.</div><div class=\"def\"><num>②</num> 二つの.</div><div class=\"def\"><num>③</num> 一対の</div><div class=\"ex\"><i>boves</i> ～ (<author>P<small>LAUT</small></author>)<span class=\"ext\">一対の牛.</span></div>\r\n","<div class=\"hw\">Bīsaltae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビーサルタエ, <SUP>*</SUP>-タイ《Thracia の Strymon 河畔にいた一部族》.</div>\r\n","<div class=\"hw\">Bīsalti(c)a</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビーサルティカ, <SUP>*</SUP>-ティアー《Bisaltae 族の国》.</div>\r\n","<div class=\"hw\">Bīsaltis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Thracia の王 Bisaltes の娘(=Theophane)《Neptunus に愛されて雌羊に変えられた》.</div>\r\n","<div class=\"hw\">Bīthȳnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ビーテューニア(ー)《小アジア北西部の黒海沿岸地方;のちローマの属州》.</div>\r\n","<div class=\"hw\">Bīthȳnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bithynia の.</div>\r\n","<div class=\"hw\">Bīthȳnis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">Bithynia の女.</div>\r\n","<div class=\"hw\">Bīthȳnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Bithynia 人.</div>\r\n","<div class=\"hw\">Bīthȳnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Bīthȳnicus\">Bithynicus</a>.</div>\r\n","<div class=\"hw\">bītō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">行く.</div>\r\n","<div class=\"hw\">bōbus</div><div class=\"pos\"><i>pl dat</i>, <i>abl</i></div><div class=\"def\">⇒<a href=\"entry://bōs\">bos</a>.</div>\r\n","<div class=\"hw\">bōcula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://būcula\">bucula</a>.</div>\r\n","<div class=\"hw\">bōia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(罪人用の)首輪.</div>\r\n","<div class=\"hw\">Bōla</div><div class=\"pos\">-ae, <i>f</i>, <B>Bōlae</B> -ārum, <i>f pl</i></div><div class=\"def\">ボーラ《Latium の町》.</div>\r\n","<div class=\"hw\">bōlus<SUP>2</SUP>, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">宝石の一種.</div>\r\n","<div class=\"hw\">Bōlānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bola の.</div><div class=\"hw2\"><b>Bōlānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Bola の住民.</div>\r\n","<div class=\"hw\">bōlētar</div><div class=\"pos\">-āris, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://bōlētus\">bōlētus</a>]</div><div class=\"def\">キノコをのせる皿.</div>\r\n","<div class=\"hw\">bōlētus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘植〙キノコ.</div>\r\n","<div class=\"hw\">bōmiscus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">小祭壇(=<a href=\"entry://ārula\">arula</a>).</div>\r\n","<div class=\"hw\">bōs</div><div class=\"pos\">bovis(<i>pl gen</i> boum [bovum], <i>dat</i>, <i>abl</i> būbus [bōbus]), <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> 〘動〙牛.</div><div class=\"def\"><num>②</num> 牛皮製のむち.</div><div class=\"def\"><num>③</num> 魚の一種《おそらくヒラメ》.</div>\r\n","<div class=\"hw\">būbalion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙野生のキュウリ.</div>\r\n","<div class=\"hw\">būbalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙</div><div class=\"def\"><num>①</num> レイヨウ(羚羊)の一種.</div><div class=\"def\"><num>②</num> スイギュウ(水牛).</div>\r\n","<div class=\"hw\">Būbasis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Bubassus の.</div>\r\n","<div class=\"hw\">Būbassius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bubassus の.</div>\r\n","<div class=\"hw\">Būbassus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーバッスス, <SUP>*</SUP>ビューバッソス《Caria の町》.</div>\r\n","<div class=\"hw\">Būbastis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーバスティス《 (1) エジプトの町.(2) その地で崇拝された猫頭の女神;ローマの Diana に当たる》.</div>\r\n","<div class=\"hw\">Būbastius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Bubastis の.</div>\r\n","<div class=\"hw\">būbula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[bubulus]</div><div class=\"def\">牛肉.</div>\r\n","<div class=\"hw\">būbulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛の</div><div class=\"ex\"><i>lingua bubula</i> (<author>C<small>ATO</small></author>)<span class=\"ext\">〘植〙ウシノシタグサ.</span></div>\r\n","<div class=\"hw\">būbus</div><div class=\"pos\"><i>pl dat</i>, <i>abl</i></div><div class=\"def\">⇒<a href=\"entry://bōs\">bos</a>.</div>\r\n","<div class=\"hw\">būbīle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[bos]</div><div class=\"def\">牛舎.</div>\r\n","<div class=\"hw\">būbō</div><div class=\"pos\">-ōnis, <i>m</i>(<i>f</i>)</div><div class=\"def\">フクロウ《その鳴き声は不吉視された》.</div>\r\n","<div class=\"hw\">Būbōn</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーボーン《Lycia の町》.</div>\r\n","<div class=\"hw\">Būbōna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[bos]</div><div class=\"def\">〘神話〙ブーボーナ《ローマ人の牛の守護女神》.</div>\r\n","<div class=\"hw\">būbōnion, -um</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙=<a href=\"entry://astēr\">aster 2</a>.</div>\r\n","<div class=\"hw\">Būca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブーカ《Samnium の町》.</div>\r\n","<div class=\"hw\">būcaeda</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[bos/caedo]</div><div class=\"def\">牛殺し;牛革のむちで打たれる者.</div>\r\n","<div class=\"hw\">Būcar</div><div class=\"pos\">-aris, <i>m</i></div><div class=\"def\">=<a href=\"entry://Bocc(h)ar\">Bocc(h)ar</a>.</div>\r\n","<div class=\"hw\">Būcephala</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i>, <B>-on</B> -ī, <i>n</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーケパラ《Alexander 大王がインドに建設した町;王の愛馬 Bucephalas にちなんで名づけられた》.</div>\r\n","<div class=\"hw\">Būcephalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーケパルス, <SUP>*</SUP>-ロス《Saronicus 湾沿岸の港》.</div>\r\n","<div class=\"hw\">Būcephalās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーケパラース《「牛頭」 の意;Alexander 大王の愛馬》.</div>\r\n","<div class=\"hw\">būceras</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙コロハ.</div>\r\n","<div class=\"hw\">būcerus, -ius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">牛の角をした.</div>\r\n","<div class=\"hw\">būcina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 牧人の角笛.</div><div class=\"def\"><num>②</num> (湾曲した)らっぱ(<i>cf. </i> tuba).</div><div class=\"def\"><num>③</num> (軍隊の)信号らっぱ.</div><div class=\"def\"><num>④</num> 《詩》(Triton の)ほら貝.</div>\r\n","<div class=\"hw\">būcinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[bucina]</div><div class=\"def\"><num>①</num> らっぱの音.</div><div class=\"def\"><num>②</num> 〘貝〙エゾバイ科の貝.</div>\r\n","<div class=\"hw\">būcinus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[bucina]</div><div class=\"def\">らっぱ手.</div>\r\n","<div class=\"hw\">būcinātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://būcinō\">būcinō</a>]</div><div class=\"def\"><num>①</num> らっぱ手.</div><div class=\"def\"><num>②</num> 吹聴する人.</div>\r\n","<div class=\"hw\">būcinō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[bucina]</div><div class=\"def\">らっぱを吹く.</div>\r\n","<div class=\"hw\">Būcolica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://būcolicus\">būcolicus</a>]</div><div class=\"def\">(Theocritus や Vergilius の)牧歌, 田園詩.</div>\r\n","<div class=\"hw\">būcolicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">田園詩の, 牧歌の.</div>\r\n","<div class=\"hw\">būcolista</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">田園詩人.</div>\r\n","<div class=\"hw\">būcrānium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 《碑》牛の頭.</div><div class=\"def\"><num>②</num> 〘植〙キンギョソウ.</div>\r\n","<div class=\"hw\">būcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[bos]</div><div class=\"def\">(未経産の)若い雌牛.</div>\r\n","<div class=\"hw\">būculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[bos]</div><div class=\"def\">若い雄牛.</div>\r\n","<div class=\"hw\">Būdīnī</div><div class=\"pos\">-orum, <i>m pl</i></div><div class=\"def\">ブーディーニー《Sarmatia の一部族》.</div>\r\n","<div class=\"hw\">būfō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘動〙ヒキガエル.</div>\r\n","<div class=\"hw\">būglossos</div><div class=\"pos\">-ī, <i>f</i>, <B>būglossa</B> -ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ウシノシタグサ.</div>\r\n","<div class=\"hw\">būleuta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">評議員.</div>\r\n","<div class=\"hw\">būleutērium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">評議会場.</div>\r\n","<div class=\"hw\">būlē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(ギリシアのポリスの)評議会.</div>\r\n","<div class=\"hw\">būlīmia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙過食症.</div>\r\n","<div class=\"hw\">būlīmiacus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://būlīmia\">būlīmia</a>]</div><div class=\"def\">過食症の.</div>\r\n","<div class=\"hw\">būlīmiōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://būlīmus\">būlīmus</a>]</div><div class=\"def\">食欲過度の.</div>\r\n","<div class=\"hw\">būlīmus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">食欲過度.</div>\r\n","<div class=\"hw\">būmammus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[bos/mamma]</div><div class=\"def\">(ブドウが)大きな房の.</div>\r\n","<div class=\"hw\">būmastus<SUP>1</SUP></div><div class=\"pos\">-us -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">大きな房のブドウがなる.</div><hr><div class=\"hw\">būmastus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">同上の品種.</div>\r\n","<div class=\"hw\">būmelia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙セイヨウトネリコ.</div>\r\n","<div class=\"hw\">būnias</div><div class=\"pos\">-adis, <i>f</i>, <B>būnion</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙アブラナ属の植物.</div>\r\n","<div class=\"hw\">būpaes</div><div class=\"pos\">-dis, <i>m</i>, <B>būpaeda</B> -ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">巨大な少年.</div>\r\n","<div class=\"hw\">Būpalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">プーパルス, <SUP>*</SUP>-ロス《Chios 島出身の彫刻家(前6世紀)》.</div>\r\n","<div class=\"hw\">būphthalmos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> キク科の植物.</div><div class=\"def\"><num>②</num> クモノスバンダイソウ属の植物.</div>\r\n","<div class=\"hw\">būprestis</div><div class=\"pos\">-tidis(<i>acc</i> -tim), <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙毒をもった甲虫《特に牛を刺してはれものを生じさせる》.</div><div class=\"def\"><num>②</num> 野菜の一種.</div>\r\n","<div class=\"hw\">būra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">犂<SUB>すき</SUB>の柄.</div>\r\n","<div class=\"hw\">Būra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブーラ《Achaia の町》.</div>\r\n","<div class=\"hw\">būris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://būra\">bura</a>.</div>\r\n","<div class=\"hw\">Būris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://Būra\">Bura</a>.</div>\r\n","<div class=\"hw\">Būrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ブーリー《Marcomanni 族と Quadi 族の近隣にいたゲルマン系一部族》.</div>\r\n","<div class=\"hw\">būselīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙パセリの一種.</div>\r\n","<div class=\"hw\">būsequa</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[bos/sequor]</div><div class=\"def\">牛飼い.</div>\r\n","<div class=\"hw\">Būsīris</div><div class=\"pos\">-ridis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ブーシーリス《エジプトの王;異邦人をとらえて神へのいけにえにしていたが Hercules に殺された》.</div>\r\n","<div class=\"hw\">būteō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘鳥〙タカの一種.</div>\r\n","<div class=\"hw\">Būthrōtius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Buthrotum の.</div><div class=\"hw2\"><b>Būthrōtiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Buthrotum の住民.</div>\r\n","<div class=\"hw\">Būthrōtum, -on</div><div class=\"pos\">-ī, <i>n</i>, <B>-os</B> -ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブートロートゥム, <SUP>*</SUP>-トン《Epirus の港町》.</div>\r\n","<div class=\"hw\">būthysia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">牛をいけにえにささげること.</div>\r\n","<div class=\"hw\">būthytēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">牛をいけにえにささげる人.</div>\r\n","<div class=\"hw\">būtiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘鳥〙サンカノゴイ.</div>\r\n","<div class=\"hw\">būtȳrum, būtūrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">バター.</div>\r\n"]);
